(function(A){Object.assign(A.D,{"G1922":{"l":"ἐπίγνωσις","o":20,"ar":"<f>† <o>ἐπί-γνωσις</o>، <g>-εως, ἡ</g></f> <s><b>معرفة، تمييز، إدراك</b>: <r v=\"Phil.1.9\"></r>، <r v=\"Col.3.10\"></r>؛ مع المضاف إليه للشيء، <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>، <r v=\"Phlm.1.6\"></r>؛ <g>τ. ἀληθείας</g>، <r v=\"1Tim.2.4\"></r>، <r v=\"2Tim.2.25\"></r> <r v=\"2Tim.3.7\"></r>، <r v=\"Titus.1.1\"></r>، <r v=\"Heb.10.26\"></r>؛ <g>τ. ἁμαρτίας</g>، <r v=\"Rom.3.20\"></r>؛ مع المضاف إليه للشخص، عن الله: <r v=\"Eph.1.17\"></r>، <r v=\"Col.1.10\"></r>، <r v=\"2Pet.1.2\"></r>، <r v=\"2Pet.1.3\"></r>؛ عن المسيح: <r v=\"Eph.4.13\"></r>، <r v=\"2Pet.1.8\"></r> <r v=\"2Pet.2.20\"></r>؛ عن الله والمسيح: <r v=\"2Pet.1.2\"></r>؛ <g>κατ</g> ̓ <g>ἐ.</g>، <r v=\"Rom.10.2\"></r>؛ <g>ἔχειν ἐν ἐ.</g>، <r v=\"Rom.1.28\"></r> (قارن <r v=\"Col.1.9\"></r>؛ <g>αἴσθησις</g>).†</s>","en":"<f>† <o>ἐπί-γνωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιγινώσκω</g>, q.v.), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.7.14\"></r> (B. <g>γν-</g>), <r v=\"Prov.2.5\"></r>, <r v=\"Hos.4.1\"></r>, <r v=\"Hos.4.6\"></r> <r v=\"Hos.6.6\"></r> (<h n=\"H1847\">דַּעַת</h>), <r v=\"Jdt.9.14\"></r>, <r v=\"2Macc.9.11\"></r> * ;]</e> </et> <s><b>acquaintance, discernment, recognition</b> (Plut., al.): <r v=\"Phil.1.9\"></r>, <r v=\"Col.3.10\"></r>; c. gen. rei, <r v=\"Col.1.9\"></r> <r v=\"Col.2.2\"></r>, <r v=\"Phlm.1.6\"></r>; <g>τ. ἀληθείας</g>, <r v=\"1Tim.2.4\"></r>, <r v=\"2Tim.2.25\"></r> <r v=\"2Tim.3.7\"></r>, <r v=\"Titus.1.1\"></r>, <r v=\"Heb.10.26\"></r>; <g>τ. ἁμαρτίας</g>, <r v=\"Rom.3.20\"></r>; c. gen. pers., of God: <r v=\"Eph.1.17\"></r>, <r v=\"Col.1.10\"></r>, <r v=\"2Pet.1.2\"></r>, <r v=\"2Pet.1.3\"></r>; of Christ: <r v=\"Eph.4.13\"></r>, <r v=\"2Pet.1.8\"></r> <r v=\"2Pet.2.20\"></r>; of God and Christ: <r v=\"2Pet.1.2\"></r>; <g>κατ</g> ̓ <g>ἐ.</g>, <r v=\"Rom.10.2\"></r>; <g>ἔχειν ἐν ἐ.</g>, <r v=\"Rom.1.28\"></r> (v. AR, <i>Eph.</i>, 248 ff.; and for a somewhat different view, Thayer, s.v.; Lft. on <r v=\"Col.1.9\"></r>; Tr., <i>Syn.</i>, lxxv; Cremer, 159 f.; cf. <g>αἴσθησις</g>).†</s>"},"G1939":{"l":"ἐπιθυμία","o":38,"ar":"<f><o>ἐπιθυμία</o>، <g>-ας, ἡ</g></f> <s><b>رغبة، اشتياق، شهوة</b>: <r v=\"Luke.22.15\"></r> (انظر تحت مدخل <g>ἐπιθυμέω</g>)، <r v=\"Phil.1.23\"></r>، <r v=\"1Thess.2.17\"></r>، <r v=\"Rev.18.14\"></r>؛ في الجمع، <r v=\"Mark.4.19\"></r>؛ خاصةً بالإشارة إلى الأمور المحرّمة، <b>شهوة، شهوة رديئة</b> : <r v=\"Rom.7.7\"></r>، <r v=\"Rom.7.8\"></r>، <r v=\"Jas.1.14\"></r>، <r v=\"Jas.1.15\"></r>، <r v=\"2Pet.1.4\"></r>؛ في الجمع، <r v=\"Gal.5.24\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"2Tim.2.22\"></r> <r v=\"2Tim.4.3\"></r>، <r v=\"1Pet.1.14\"></r> <r v=\"1Pet.4.2\"></r>؛ <g>πάθος ἐπιθυμίας</g>، <r v=\"1Thess.4.5\"></r>؛ <g>ἐ. κακή</g>، <r v=\"Col.3.5\"></r>؛ مع المضاف إليه، <g>μιασμοῦ</g>، <r v=\"2Pet.2.10\"></r>؛ <g>τ. καρδιῶν</g>، <r v=\"Rom.1.24\"></r>؛ <g>τ. κόσμου</g> (التي يثيرها العالم)، <r v=\"1John.2.17\"></r>؛ <g>τ. σώματος</g>، <r v=\"Rom.6.12\"></r>؛ <g>τ. ἀπάτης</g>، <r v=\"Eph.4.22\"></r>؛ <g>τ. σαρκός</g>، <r v=\"1John.2.16\"></r>، <r v=\"2Pet.2.18\"></r> (بدون أداة التعريف)، <r v=\"Gal.5.16\"></r>؛ <g>τ. ὀφθαλμῶν</g>، <r v=\"1John.2.16\"></r>؛ <g>σαρκικαὶ ἐ.</g>، <r v=\"1Pet.2.11\"></r> (قارن <r v=\"4Macc.1.32\"></r>)؛ <g>κοσμικαί</g>، <r v=\"Titus.2.12\"></r>؛ <g>εἰς ἐπιθυμίας</g>، <r v=\"Rom.13.14\"></r>؛ <g>ποιεῖν τὰς ἐ.</g>، <r v=\"John.8.44\"></r>؛ <g>ὑπακούειν ταῖς ἐ.</g>، <r v=\"Rom.6.12\"></r>؛ <g>δουλεύειν, ἄγεσθαι, ἐπιθυμίαις</g>، <r v=\"Titus.3.3\"></r>، <r v=\"2Tim.3.6\"></r>؛ <g>πορεύειθαι ἐν ἐ.</g>، <r v=\"1Pet.4.3\"></r>؛ <g>κατά</g>، <r v=\"Jude.1.16\"></r>، <r v=\"Jude.1.18\"></r>، <r v=\"2Pet.3.3\"></r>؛ <g>ἀναστρέφεσθαι ἐν ταῖς ἐ.</g>، <r v=\"Eph.2.3\"></r>.†</s>","en":"<f><o>ἐπιθυμία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>έπιθυμέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8378\">תַּאֲוָה</h>, <h n=\"H183\">אָוָה</h>; also for <h n=\"H2531\">חָמוּד</h>, etc. ;] </e> </et> <s><b>desire, longing</b>: <r v=\"Luke.22.15\"></r> (v.s. <g>ἐπιθυμέω</g>), <r v=\"Phil.1.23\"></r>, <r v=\"1Thess.2.17\"></r>, <r v=\"Rev.18.14\"></r>; p1., <r v=\"Mark.4.19\"></r>; esp. with ref. to forbidden things, <b>desire, lust</b> (Vg., <l>concupiscentia</l>): <r v=\"Rom.7.7\"></r>, <r v=\"Rom.7.8\"></r>, <r v=\"Jas.1.14\"></r>, <r v=\"Jas.1.15\"></r>, <r v=\"2Pet.1.4\"></r>; pl., <r v=\"Gal.5.24\"></r>, <r v=\"1Tim.6.9\"></r>, <r v=\"2Tim.2.22\"></r> <r v=\"2Tim.4.3\"></r>, <r v=\"1Pet.1.14\"></r> <r v=\"1Pet.4.2\"></r>; <g>πάθος ἐπιθυμίας</g>, <r v=\"1Thess.4.5\"></r>; <g>ἐ. κακή</g>, <r v=\"Col.3.5\"></r>; c. gen., <g>μιασμοῦ</g>, <r v=\"2Pet.2.10\"></r> (v. Mayor, in l.); <g>τ. καρδιῶν</g>, <r v=\"Rom.1.24\"></r>; <g>τ. κόσμου</g> (aroused by the world), <r v=\"1John.2.17\"></r>; <g>τ. σώματος</g>, <r v=\"Rom.6.12\"></r>; <g>τ. ἀπάτης</g>, <r v=\"Eph.4.22\"></r> (v. <i>ICC</i>, in l.); <g>τ. σαρκός</g>, <r v=\"1John.2.16\"></r>, <r v=\"2Pet.2.18\"></r> (without art.), <r v=\"Gal.5.16\"></r>; <g>τ. ὀφθαλμῶν</g>, <r v=\"1John.2.16\"></r>; <g>σαρκικαὶ ἐ.</g>, <r v=\"1Pet.2.11\"></r> (cf. <r v=\"4Macc.1.32\"></r>); <g>κοσμικαί</g>, <r v=\"Titus.2.12\"></r>; <g>εἰς ἐπιθυμίας</g>, <r v=\"Rom.13.14\"></r>; <g>ποιεῖν τὰς ἐ.</g>, <r v=\"John.8.44\"></r>; <g>ὑπακούειν ταῖς ἐ.</g>, <r v=\"Rom.6.12\"></r>; <g>δουλεύειν, ἄγεσθαι, ἐπιθυμίαις</g>, <r v=\"Titus.3.3\"></r>, <r v=\"2Tim.3.6\"></r>; <g>πορεύειθαι ἐν ἐ.</g>, <r v=\"1Pet.4.3\"></r>; <g>κατά</g>, <r v=\"Jude.1.16\"></r>, <r v=\"Jude.1.18\"></r>, <r v=\"2Pet.3.3\"></r>; <g>ἀναστρέφεσθαι ἐν ταῖς ἐ.</g>, <r v=\"Eph.2.3\"></r>.†</s> <sy><i>SYN.</i>: <g>πάθος</g> (q.v.), <g>ὄρεξις</g> </sy>"},"G1904":{"l":"ἐπεισέρχομαι","o":null,"ar":"<f>* <o>ἐπ-εισ-έρχομαι </o></f> <s><b>يدهم، يأتي على، يأتي فجأة على</b>: يليه <g>ἐπί</g> <r v=\"Luke.21.35\"></r>.†</s>","en":"<f>* <o>ἐπ-εισ-έρχομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.16.16\"></r> (c. dat.) * ;] </e> </et> <s><b>to come in upon</b>: seq. <g>ἐπί</g> <r v=\"Luke.21.35\"></r>.†</s>"},"G1931":{"l":"ἐπιδύω","o":1,"ar":"<f><o>ἐπι-δύω </o></f> <s><b>يغرب، يغيب</b> (عن الشمس): <r v=\"Eph.4.26\"></r>.†</s>","en":"<f><o>ἐπι-δύω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.24.15\"></r>, <r v=\"Josh.8.29\"></r>, <r v=\"Jer.15.9\"></r> (<h n=\"H935\">בּוֹא</h>)* ;]</e> </et> <s><b>to go down, set</b> (of the sun): <r v=\"Eph.4.26\"></r>.†</s>"},"G1909":{"l":"ἐπί","o":1758,"ar":"<f><o>ἐπί</o> (قبل النَّفَس الخفيف <g>ἐπ’</g>، وقبل النَّفَس الثقيل <g>ἐφ’</g>)، </f> حرف جر مع المضاف إليه والقابل والمنصوب (والمنصوب هو الأكثر في العهد الجديد)، <s>معناه الأساسي الفوقية (الوضع فوق شيء)، <b>على، فوق</b>. <s n=\"I.\">مع المضاف إليه، <s n=\"1.\">للمكان، جوابًا عن السؤال: أين؟ <s n=\"(a)\">للمكان الذي يكون عليه الشيء، <b>على، فوق</b>: <g>ἐπὶ (τ.) γῆς</g>، <r v=\"Matt.6.10\"></r>، <r v=\"Matt.6.19\"></r>، وفي مواضع أخرى؛ <g>τ. κεφαλῆς</g>، <r v=\"1Cor.11.10\"></r>؛ <g>τ. νεφελῶν</g>، <r v=\"Matt.24.30\"></r>، وفي مواضع أخرى؛ مثل <g>ἐν</g>، في تركيب مضمَّن بعد أفعال الحركة: <g>βάλλειν</g>، <r v=\"Mark.4.26\"></r>؛ <g>σπείρειν</g>، <r v=\"Mark.4.31\"></r>؛ <g>ἔρχεσθαι</g>، <r v=\"Heb.6.7\"></r>، وفي مواضع أخرى؛ مجازيًا، <g>ἐπ’ ἀληθείας</g>؛ عن موضوع الفكر أو الكلام، <r v=\"Gal.3.16\"></r>؛ عن القوة أو السلطان، <b>على</b>، <g>πάντων</g>، <r v=\"Rom.9.5\"></r>: <g>τ. γάζης</g>، <r v=\"Acts.8.27\"></r>؛ <g>ἐξουσία</g>، <r v=\"Rev.2.26\"></r> <r v=\"Rev.20.6\"></r>؛ </s> <s n=\"(b)\">للقرب، <b>عند، بجانب</b>: <g>τ. θαλάσσης</g>، <r v=\"John.6.9\"></r>؛ <g>τ. ὁδοῦ</g>، <r v=\"Matt.21.19\"></r>؛ <g>τοῦ βάτου</g>، <r v=\"Mark.12.26\"></r>؛ مع المضاف إليه للأشخاص، <b>في حضرة، أمام</b>، <r v=\"Matt.28.14\"></r>، <r v=\"Acts.23.30\"></r>، <r v=\"1Cor.6.1\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"2.\">للزمان، <s n=\"(a)\">مع المضاف إليه للأشخاص، <b>في زمن</b>: <g>ἐπὶ Ἐλισαίου</g>، <r v=\"Luke.4.27\"></r>؛ <g>ἐπὶ Κλαυδίου</g>، <r v=\"Acts.11.28\"></r>؛ <g>ἐπὶ Ἀβιάθαρ ἀρχιερέως</g>، <b>حين كان أبياثار رئيسًا للكهنة</b>، <r v=\"Mark.2.26\"></r>؛ </s> <s n=\"(b)\">مع المضاف إليه للأشياء، <b>عند، في وقت</b>: <r v=\"Matt.1.11\"></r>، <r v=\"Heb.1.2\"></r>، <r v=\"2Pet.3.3\"></r>؛ <g>ἐπὶ τ. προσευχῶν</g>، <r v=\"Rom.1.10\"></r>، <r v=\"Eph.1.16\"></r>، <r v=\"1Thess.1.2\"></r>، <r v=\"Phlm.1.4\"></r>. </s> </s> </s> <s n=\"II.\">مع القابل، للمكان، جوابًا عن السؤال: أين؟ <s n=\"(a)\">حرفيًا، <b>على، فوق</b>: <r v=\"Matt.9.16\"></r>، <r v=\"Matt.14.8\"></r>، وفي مواضع أخرى؛ بعد أفعال الحركة (انظر أعلاه، I، 1، (<i>a</i>))، <r v=\"Matt.9.16\"></r> <r v=\"Acts.8.16\"></r>؛ <b>فوق</b>، <r v=\"Luke.23.38\"></r>؛ <b>عند، بجانب</b>، <r v=\"Mark.13.29\"></r>، <r v=\"John.5.2\"></r>، <r v=\"Acts.5.9\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">مجازيًا، <b>على، على أساس</b>، <r v=\"Luke.4.4\"></r> <i>(السبعينية)</i>؛ <b>في أمر</b>، <r v=\"Mark.6.52\"></r>؛ <b>على، عن، بخصوص</b>، <r v=\"Acts.5.35\"></r>، <r v=\"Acts.5.40\"></r>؛ عن الأساس أو السبب أو الدافع، <r v=\"Matt.18.3\"></r> <r v=\"Matt.19.9\"></r>، <r v=\"Rom.12.12\"></r>، وفي مواضع أخرى؛ <g>ἐφ’ ᾧ</g>، <b>لأنه، بسبب أن</b>، <r v=\"Rom.5.12\"></r> <r v=\"2Cor.5.4\"></r>؛ بعد أفعال الحركة، <b>على (فرحًا ونحوه)</b>، <r v=\"Matt.18.13\"></r>، <r v=\"Rom.16.19\"></r>، وفي مواضع أخرى؛ عن الشرط، <r v=\"Rom.8.20\"></r>، <r v=\"1Cor.9.10\"></r>؛ <g>ἐπὶ δυσὶ μάρτυσιν</g> (قارن <r v=\"Heb.9.10\"></r>)، <r v=\"Heb.10.28\"></r>؛ عن القصد أو الغاية، <r v=\"Eph.2.10\"></r>، <r v=\"Phil.4.10\"></r>؛ عن السلطان، <b>على</b>، <r v=\"Matt.24.47\"></r> <r v=\"Luke.12.44\"></r>؛ عن العداوة، مع القابل للأشخاص، <b>على، ضد</b>، <r v=\"Luke.12.52\"></r>؛ <b>بالإضافة إلى</b>، <r v=\"2Cor.7.13\"></r>؛ عن أمر مصاحب، <b>في، عند، على</b>، <r v=\"Phil.1.3\"></r> <r v=\"Phil.2.17\"></r>. </s> </s> <s n=\"III.\">مع المنصوب، <s n=\"1.\">لمكان الحركة على شيء أو فوقه، جوابًا عن السؤال: إلى أين؟ <s n=\"(a)\">حرفيًا، <b>على، فوق</b>: <r v=\"Matt.14.28\"></r>، <r v=\"Matt.14.29\"></r>، <r v=\"Luke.5.19\"></r>، وفي مواضع أخرى كثيرة؛ وفي العهد الجديد أيضًا جوابًا عن السؤال: أين؟ (كما مع المضاف إليه والقابل)، <r v=\"Mark.4.38\"></r> <r v=\"Mark.11.2\"></r>، <r v=\"Luke.2.25\"></r>، <r v=\"John.1.32\"></r>؛ <g>ἐπὶ τ. αὐτό</g>، <r v=\"Acts.1.15\"></r> <r v=\"Acts.2.1\"></r>، وفي مواضع أخرى؛ عن الحركة إلى مكان قريب، <b>إلى</b>، <r v=\"Mark.16.2\"></r>، <r v=\"Acts.8.36\"></r>، وفي مواضع أخرى؛ </s> <s n=\"(b)\">مجازيًا (وفيه يكثر المنصوب أكثر مما ينبغي بحسب القاعدة الدقيقة)؛ عن البركات والشرور ونحوها التي تحل على أحد، مع المنصوب للأشخاص، <r v=\"Matt.10.13\"></r> <r v=\"Matt.12.28\"></r>، <r v=\"Acts.2.17\"></r>، <r v=\"John.18.4\"></r>، <r v=\"Eph.5.6\"></r>، وفي مواضع أخرى؛ عن الإضافة، <g>λύπη ἐπὶ λύπην</g>، <r v=\"Phil.2.27\"></r>؛ <g>ἐπικαλεῖν ὄνομα ἐπί</g> (انظر تحت مدخل <g>ἐπικαλέω</g>)، <r v=\"Acts.15.17\"></r>، <r v=\"Jas.2.7\"></r>؛ <g>καλεῖν ἐπί</g>، <b>أن يُسمَّى باسم</b>، <r v=\"Luke.1.59\"></r>؛ عن العدد أو الدرجة: <g>ἐπὶ τρίς</g>، <b>ثلاث مرات</b>، <r v=\"Acts.10.16\"></r> <r v=\"Acts.11.10\"></r>؛ <g>ἐπὶ πλεῖον</g>، <b>أكثر، أبعد</b>، <r v=\"Acts.4.17\"></r> <r v=\"2Tim.2.16\"></r> <r v=\"2Tim.3.9\"></r> (انظر أيضًا أدناه، 2، (<i>a</i>))؛ <g>ἐφ’ ὅσον</g> (انظر أدناه، في الموضع نفسه)، <b>بما أنَّ، بقدر ما</b>، <r v=\"Matt.25.40\"></r>، <r v=\"Matt.25.45\"></r>، <r v=\"Rom.11.13\"></r>؛ عن القوة والسلطان والسيطرة، <r v=\"Luke.1.33\"></r>، <r v=\"Acts.7.10\"></r> <r v=\"Rom.5.14\"></r>، <r v=\"Heb.3.6\"></r>، وفي مواضع أخرى؛ عن اتجاه الأفكار والمشاعر، <b>إلى، نحو</b>، <r v=\"Luke.1.17\"></r> <r v=\"Luke.23.28\"></r>، <r v=\"Acts.9.35\"></r>، <r v=\"Acts.9.42\"></r>، <r v=\"Acts.11.22\"></r>، <r v=\"Gal.4.9\"></r>، <r v=\"Eph.2.7\"></r>، <r v=\"1Tim.5.5\"></r>، وفي مواضع أخرى؛ عن القصد، <b>لأجل</b>، <r v=\"Matt.3.7\"></r>، <r v=\"Luke.23.48\"></r>؛ <g>ἐφ’ ὅ πάρει</g>، <r v=\"Matt.26.50\"></r>؛ عن العداوة، <b>على، ضد</b>، <r v=\"Matt.24.7\"></r>، <r v=\"Mark.3.24-Mark.3.26\"></r> <r v=\"Mark.10.11\"></r> <r v=\"Mark.13.8\"></r>، <r v=\"Luke.9.5\"></r>، <r v=\"John.13.18\"></r>، <r v=\"Acts.7.54\"></r>، <r v=\"1Cor.7.36\"></r>، <r v=\"2Cor.1.23\"></r>؛ عن الإشارة إلى أمر، <b>بخصوص، عن</b>، <r v=\"Mark.9.12\"></r> <r v=\"Mark.15.24\"></r>، <r v=\"John.19.24\"></r>، <r v=\"Rom.4.9\"></r>. </s> </s> <s n=\"2.\">للزمان، <s n=\"(a)\"><b>أثناء، مدة</b>: <r v=\"Luke.4.25\"></r>، <r v=\"Acts.13.31\"></r> <r v=\"Acts.16.18\"></r>، <r v=\"Heb.11.30\"></r>، وفي مواضع أخرى؛ <g>ἐφ’ ὅσον (χρόνον)</g>، <b>ما دام، طوال المدة التي</b>، <r v=\"Mark.9.15\"></r> <r v=\"Rom.7.1\"></r>، وفي مواضع أخرى (وعن <g>ἐφ’ ὅ</g> بمعنى آخر، انظر أعلاه، 1، (<i>b</i>))؛ <g>ἐφ’ ἱκανόν</g> (انظر تحت مدخل <g>ἱ</g>)، <r v=\"Acts.20.11\"></r>؛ <g>ἐπὶ πλεῖον</g> (انظر أعلاه، 1، (b))، <b>مدة أطول، أكثر</b>، <r v=\"Acts.20.9\"></r> <r v=\"Acts.24.4\"></r>؛ </s> <s n=\"(b)\"><b>في، نحو، قرابة</b>: <r v=\"Luke.10.35\"></r> <r v=\"Acts.3.1\"></r> <r v=\"Acts.4.5\"></r>. </s> </s> </s> <s n=\"IV.\">في التركيب، تدل <g>ἐπί</g> على: <b>فوق (إلى أعلى)</b>، <g>ἐπαίρω</g>؛ <b>على</b>، <g>ἐπίγειος, ἐπιδημέω, ἐπικαθίζω</g>؛ <b>نحو</b>، <g>επιβλέπω, ἐπεκτείνω</g>؛ <b>على</b> (بمعنى الإشراف)، <g>ἐπιστάτης</g>؛ <b>ثانيةً، بالإضافة</b>، <g>ἐπαιτέω</g>؛ <b>ضد</b>، <g>ἐπιορκέω, ἐπιβουλή</g>.</s> </s>","en":"<f><o>ἐπί</o> (before a smooth breathing <g>ἐπ’</g>, before a rough breathing <g>ἐφ’</g>), </f> prep. c. gen., dat., acc. (acc. most freq. in NT), <s>with primary sense of superposition, <b>on, upon</b>. <s n=\"I.\">C. gen., <s n=\"1.\">of place, answering the question, where? <s n=\"(a)\">of the place on which, <b>on, upon</b>: <g>ἐπὶ (τ.) γῆς</g>, <r v=\"Matt.6.10\"></r>, <r v=\"Matt.6.19\"></r>, al.; <g>τ. κεφαλῆς</g>, <r v=\"1Cor.11.10\"></r>; <g>τ. νεφελῶν</g>, <r v=\"Matt.24.30\"></r>, al.; like <g>ἐν</g>, in <l>constr. praegn.</l> after verbs of motion: <g>βάλλειν</g>, <r v=\"Mark.4.26\"></r>; <g>σπείρειν</g>, <r v=\"Mark.4.31\"></r>; <g>ἔρχεσθαι</g>, <r v=\"Heb.6.7\"></r>, al.; fig., <g>ἐπ’ ἀληθείας</g> (MM, s.v. <g>ἀ.</g>); of the subject of thought or speech, <r v=\"Gal.3.16\"></r>; of power or authority, <b>over</b>, <g>πάντων</g>, <r v=\"Rom.9.5\"></r>: <g>τ. γάζης</g>, <r v=\"Acts.8.27\"></r>; <g>ἐξουσία</g>, <r v=\"Rev.2.26\"></r> <r v=\"Rev.20.6\"></r>; </s> <s n=\"(b)\">of vicinity, <b>at, by</b>: <g>τ. θαλάσσης</g>, <r v=\"John.6.9\"></r>; <g>τ. ὁδοῦ</g>, <r v=\"Matt.21.19\"></r>; <g>τοῦ βάτου</g>, <r v=\"Mark.12.26\"></r> (v. Swete, in l.); c. gen. pers., <b>in the presence of, before</b>, <r v=\"Matt.28.14\"></r>, <r v=\"Acts.23.30\"></r>, <r v=\"1Cor.6.1\"></r>, al. </s> </s> <s n=\"2.\">Of time, <s n=\"(a)\">c. gen. pers., <b>in the time of</b>: <g>ἐπὶ Ἐλισαίου</g>, <r v=\"Luke.4.27\"></r>; <g>ἐπὶ Κλαυδίου</g>, <r v=\"Acts.11.28\"></r>; <g>ἐπὶ Ἀβιάθαρ ἀρχιερέως</g>, <b>when A. was high priest</b>, <r v=\"Mark.2.26\"></r>; </s> <s n=\"(b)\">c. gen. rei, <b>at, at the time of</b>: <r v=\"Matt.1.11\"></r>, <r v=\"Heb.1.2\"></r>, <r v=\"2Pet.3.3\"></r>; <g>ἐπὶ τ. προσευχῶν</g>, <r v=\"Rom.1.10\"></r>, <r v=\"Eph.1.16\"></r>, <r v=\"1Thess.1.2\"></r>, <r v=\"Phlm.1.4\"></r>. </s> </s> </s> <s n=\"II.\">C. dat., of place, answering the question, where? <s n=\"(a)\">lit., <b>on, upon</b>: <r v=\"Matt.9.16\"></r>, <r v=\"Matt.14.8\"></r>, al.; after verbs of motion (v. supr., I, 1, (<i>a</i>)), <r v=\"Matt.9.16\"></r> <r v=\"Acts.8.16\"></r>; <b>above</b>, <r v=\"Luke.23.38\"></r>; <b>at, by</b>, <r v=\"Mark.13.29\"></r>, <r v=\"John.5.2\"></r>, <r v=\"Acts.5.9\"></r>, al.; </s> <s n=\"(b)\">metaph., <b>upon, on the ground of</b>, <r v=\"Luke.4.4\"></r> <i>(LXX)</i>; <b>in the matter of</b>, <r v=\"Mark.6.52\"></r> (v. Swete, in l.); <b>upon, of, concerning</b>, <r v=\"Acts.5.35\"></r>, <r v=\"Acts.5.40\"></r>; of the ground, reason or motive (Bl., §38, 2; 43, 3), <r v=\"Matt.18.3\"></r> <r v=\"Matt.19.9\"></r>, <r v=\"Rom.12.12\"></r>, al.; <g>ἐφ’ ᾧ</g>, <b>for the reason that, because</b>, <r v=\"Rom.5.12\"></r> <r v=\"2Cor.5.4\"></r>; after verbs of motion, <b>over</b>, <r v=\"Matt.18.13\"></r>, <r v=\"Rom.16.19\"></r>, al.; of a condition (cl.), <r v=\"Rom.8.20\"></r>, <r v=\"1Cor.9.10\"></r>; <g>ἐπὶ δυσὶ μάρτυσιν</g> (v. Westc. on <r v=\"Heb.9.10\"></r>), <r v=\"Heb.10.28\"></r>; of purpose or aim, <r v=\"Eph.2.10\"></r>, <r v=\"Phil.4.10\"></r>; of authority, <b>over</b>, <r v=\"Matt.24.47\"></r> <r v=\"Luke.12.44\"></r>; of hostility, c. dat. pers. (cl.), <b>against</b>, <r v=\"Luke.12.52\"></r>; <b>in addition to</b> (cl.), <r v=\"2Cor.7.13\"></r>; of an adjunct, <b>in, at, on</b>, <r v=\"Phil.1.3\"></r> <r v=\"Phil.2.17\"></r>. </s> </s> <s n=\"III.\">C. acc., <s n=\"1.\">of place of motion upon or over, answering the question, whither? <s n=\"(a)\">lit., <b>upon, over</b>: <r v=\"Matt.14.28\"></r>, <r v=\"Matt.14.29\"></r>, <r v=\"Luke.5.19\"></r>, al. mult.; in NT also, answering the question, where? (as c. gen., dat.), <r v=\"Mark.4.38\"></r> <r v=\"Mark.11.2\"></r>, <r v=\"Luke.2.25\"></r>, <r v=\"John.1.32\"></r>; <g>ἐπὶ τ. αὐτό</g>, <r v=\"Acts.1.15\"></r> <r v=\"Acts.2.1\"></r>, al.; of motion to a vicinity, <b>to</b>, <r v=\"Mark.16.2\"></r>, <r v=\"Acts.8.36\"></r>, al.; </s> <s n=\"(b)\">metaph. (in wh. \"the acc. is more widely prevalent than it strictly should be,\" Bl., §43, 1); of blessings, evils, etc., coming upon one, c. acc. pers., <r v=\"Matt.10.13\"></r> <r v=\"Matt.12.28\"></r>, <r v=\"Acts.2.17\"></r>, <r v=\"John.18.4\"></r>, <r v=\"Eph.5.6\"></r>, al.; of addition (dat. in cl.), <g>λύπη ἐπὶ λύπην</g>, <r v=\"Phil.2.27\"></r>; <g>ἐπικαλεῖν ὄνομα ἐπί</g> (v.s. <g>ἐπικαλέω</g>), <r v=\"Acts.15.17\"></r>, <r v=\"Jas.2.7\"></r>; <g>καλεῖν ἐπί</g>, <b>to call after</b>, <r v=\"Luke.1.59\"></r>; of number or degree: <g>ἐπὶ τρίς</g> (cl. <g>εἰς τ.</g>), <b>thrice</b>, <r v=\"Acts.10.16\"></r> <r v=\"Acts.11.10\"></r>; <g>ἐπὶ πλεῖον</g>, <b>the more, further</b>, <r v=\"Acts.4.17\"></r> <r v=\"2Tim.2.16\"></r> <r v=\"2Tim.3.9\"></r> (v. also infr., 2, (<i>a</i>)); <g>ἐφ’ ὅσον</g> (v. infr., ib.), <b>forasmuch as</b>, <r v=\"Matt.25.40\"></r>, <r v=\"Matt.25.45\"></r>, <r v=\"Rom.11.13\"></r>; of power, authority, control, <r v=\"Luke.1.33\"></r>, <r v=\"Acts.7.10\"></r> <r v=\"Rom.5.14\"></r>, <r v=\"Heb.3.6\"></r>, al.; of the direction of thoughts and feelings, <b>unto, towards</b>, <r v=\"Luke.1.17\"></r> <r v=\"Luke.23.28\"></r>, <r v=\"Acts.9.35\"></r>, <r v=\"Acts.9.42\"></r>, <r v=\"Acts.11.22\"></r>, <r v=\"Gal.4.9\"></r>, <r v=\"Eph.2.7\"></r>, <r v=\"1Tim.5.5\"></r>, al.; of purpose, <b>for</b>, <r v=\"Matt.3.7\"></r>, <r v=\"Luke.23.48\"></r>; <g>ἐφ’ ὅ πάρει</g> (Rec. <g>ἐφ’ ᾧ</g>, <r v=\"Matt.26.50\"></r>; of hostility, <b>against</b>, <r v=\"Matt.24.7\"></r>, <r v=\"Mark.3.24-Mark.3.26\"></r> <r v=\"Mark.10.11\"></r> <r v=\"Mark.13.8\"></r>, <r v=\"Luke.9.5\"></r>, <r v=\"John.13.18\"></r>, <r v=\"Acts.7.54\"></r>, <r v=\"1Cor.7.36\"></r>, <r v=\"2Cor.1.23\"></r>; Of reference, <b>concerning, for</b> (cl. usually dat.), <r v=\"Mark.9.12\"></r> <r v=\"Mark.15.24\"></r>, <r v=\"John.19.24\"></r>, <r v=\"Rom.4.9\"></r>. </s> </s> <s n=\"2.\">Of time, <s n=\"(a)\"><b>during, for</b>: <r v=\"Luke.4.25\"></r> (WH, txt., omits <g>ἐπί</g>), <r v=\"Acts.13.31\"></r> <r v=\"Acts.16.18\"></r>, <r v=\"Heb.11.30\"></r>, al.; <g>ἐφ’ ὅσον (χρόνον)</g>, <b>as long as, for so long time as</b>, <r v=\"Mark.9.15\"></r> <r v=\"Rom.7.1\"></r>, al. (for <g>ἐφ’ ὅ</g> in another sense, v. supr., 1, (<i>b</i>)); <g>ἐφ’ ἱκανόν</g> (v.s. <g>ἱ</g>), <r v=\"Acts.20.11\"></r>; <g>ἐπὶ πλεῖον</g> (v. supr., 1, (b)), <b>yet longer, further</b>, <r v=\"Acts.20.9\"></r> <r v=\"Acts.24.4\"></r>; </s> <s n=\"(b)\"><b>on, about, towards</b> (cl. <g>εἰς</g>): <r v=\"Luke.10.35\"></r> <r v=\"Acts.3.1\"></r> <r v=\"Acts.4.5\"></r>. </s> </s> </s> <s n=\"IV.\">In composition, <g>ἐπί</g> signifies: <b>up</b>, <g>ἐπαίρω</g>; <b>upon</b>, <g>ἐπίγειος, ἐπιδημέω, ἐπικαθίζω</g>; <b>towards</b>, <g>επιβλέπω, ἐπεκτείνω</g>; <b>over</b> (of superintendence), <g>ἐπιστάτης</g>; <b>again, in addition</b>, <g>ἐπαιτέω</g>; <b>against</b>, <g>ἐπιορκέω, ἐπιβουλή</g>.</s> </s>"},"G1972":{"l":"ἐπιπόθησις","o":2,"ar":"<f>**† <o>ἐπι-πόθησις</o>، <g>-εως, ἡ </g></f> <s><b>شوق، اشتياق</b>: <r v=\"2Cor.7.7\"></r>، <r v=\"2Cor.7.11\"></r>.† </s>","en":"<f>**† <o>ἐπι-πόθησις</o>, <g>-εως, ἡ </g></f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Ezek.23.11\"></r> * ;] </e> </et> <s><b>longing</b>: <r v=\"2Cor.7.7\"></r>, <r v=\"2Cor.7.11\"></r>.† </s>"},"G1941":{"l":"ἐπικαλέω","o":null,"ar":"<f><o>ἐπι-καλέω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>يدعو، يسمّي، يلقّب</b>: مع المنصوب، <r v=\"Matt.10.25\"></r>؛ المبني للمجهول، <r v=\"Acts.1.23\"></r>، <r v=\"Acts.4.36\"></r>، <r v=\"Acts.10.5\"></r>، <r v=\"Acts.10.18\"></r>، <r v=\"Acts.10.32\"></r>، <r v=\"Acts.11.13\"></r>، <r v=\"Acts.12.12\"></r>، <r v=\"Acts.12.25\"></r>، <r v=\"Heb.11.16\"></r>؛ <g>τ. ὄνομα</g> يليه <g>ἐπί</g> (دلالةً على الملكية، كما في <i>العبرية</i> <h n=\"H5921\">. עַל</h> <h n=\"H7121\">נִקְרָא</h> <h n=\"H8036\">שֵׁם .</h>)، <r v=\"Acts.15.17\"></r> <i>(السبعينية)</i>، <r v=\"Jas.2.7\"></r> (قارن <r v=\"Amos.9.12\"></r>). </s> <s n=\"2.\">الصيغة الوسطى (وكذلك المبني للمعلوم): <b>يدعو، يستغيث بـ، يرفع دعواه إلى</b>: <g>Καίσαρα</g> (<g>Σεβαστόν</g>، <r v=\"Acts.25.25\"></r>)، <r v=\"Acts.25.11\"></r>، <r v=\"Acts.25.12\"></r>، <r v=\"Acts.25.21\"></r>، <r v=\"Acts.26.32\"></r>، <r v=\"Acts.28.19\"></r>؛ وبتقدير <g>τ. Κύριον Ἰησοῦν</g>، <r v=\"Acts.7.59\"></r>؛ <g>μάρτυρα</g> <g>τ. θεόν</g>، <r v=\"2Cor.1.23\"></r>؛ <g>πατέρα</g>، <r v=\"1Pet.1.17\"></r>؛ <g>τ. κύριον</g>، <r v=\"Rom.10.12\"></r>، <r v=\"2Tim.2.22\"></r>؛ <g>τ. ὄνομα κυρίου</g> (<g>μου, σου</g>؛ مثل <i>العبرية</i> <h n=\"H8036\">בְּשֵׁם</h> <h n=\"H3068\">יְהֹוָה</h> <h n=\"H7121\">קָרָא</h>)، <r v=\"Acts.2.21\"></r> <i>(السبعينية)</i>، <r v=\"Acts.9.14\"></r>، <r v=\"Acts.9.21\"></r>، <r v=\"Acts.22.16\"></r>، <r v=\"Rom.10.13\"></r>، <r v=\"Rom.10.14\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.1.2\"></r>.†</s>","en":"<f><o>ἐπι-καλέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7121\">קָרָא</h> ;] </e> </et> <s n=\"1.\"><b>to call, name, surname</b>: c. acc (cl.), <r v=\"Matt.10.25\"></r>; pass., <r v=\"Acts.1.23\"></r> <r v=\"Acts.4.36\"></r> <r v=\"Acts.10.5\"></r>, <r v=\"Acts.10.18\"></r>, <r v=\"Acts.10.32\"></r> <r v=\"Acts.11.13\"></r> <r v=\"Acts.12.12\"></r>, <r v=\"Acts.12.25\"></r>, <r v=\"Heb.11.16\"></r>; <g>τ. ὄνομα</g>, seq. <g>ἐπί</g> (denoting possession, as <i>Heb.</i> <h n=\"H5921\">. עַל</h> <h n=\"H7121\">נִקְרָא</h> <h n=\"H8036\">שֵׁם .</h>), <r v=\"Acts.15.17\"></r> <i>(LXX)</i>, <r v=\"Jas.2.7\"></r> (see. CB on <r v=\"Amos.9.12\"></r>). </s> <s n=\"2.\">Mid. (so also act.; cl., LXX), <b>to call upon, invoke, appeal to</b> (<g>θεόν, θεούς</g>, Hdt., Xen., al.; cf. Deiss., <i>LAE</i>, 426): <g>Καίσαρα</g> (<g>Σεβαστόν</g>, <r v=\"Acts.25.25\"></r>), <r v=\"Acts.25.11\"></r>, <r v=\"Acts.25.12\"></r>, <r v=\"Acts.25.21\"></r> <r v=\"Acts.26.32\"></r> <r v=\"Acts.28.19\"></r>; sc. <g>τ. Κύριον Ἰησοῦν</g>, <r v=\"Acts.7.59\"></r>; <g>μάρτυρα</g> (cl.) <g>τ. θεόν</g>, <r v=\"2Cor.1.23\"></r>; <g>πατέρα</g>, <r v=\"1Pet.1.17\"></r>; <g>τ. κύριον</g>, <r v=\"Rom.10.12\"></r>, <r v=\"2Tim.2.22\"></r>; <g>τ. ὄνομα κυρίου</g> (<g>μου, σου</g>; like <i>Heb.</i> <h n=\"H8036\">בְּשֵׁם</h> <h n=\"H3068\">יְהֹוָה</h> <h n=\"H7121\">קָרָא</h> ), <r v=\"Acts.2.21\"></r> <i>(LXX)</i> <r v=\"Acts.9.14\"></r>, <r v=\"Acts.9.21\"></r> <r v=\"Acts.22.16\"></r>, <r v=\"Rom.10.13\"></r>, <r v=\"Rom.10.14\"></r> <i>(LXX)</i> <r v=\"1Cor.1.2\"></r> (Cremer, 335, 742).†</s>"},"G1902":{"l":"ἐπενδύω","o":2,"ar":"<f>*† <o>ἐπ-εν-δύω</o></f> <s>= <g>-δύνω</g>، </s> <s><b>يلبس فوق</b>؛ المبني للمجهول: <b>يكون لابسًا فوق، يُلبَس فوقه</b>: <r v=\"2Cor.5.2\"></r>، <r v=\"2Cor.5.4\"></r>.†</s>","en":"<f>*† <o>ἐπ-εν-δύω</o></f> <s>= <g>-δύνω</g> (Hdt.), </s> <s><b>to put on over</b>; pass. (Plut., al.), <b>to have on over, be clothed upon</b>: <r v=\"2Cor.5.2\"></r>, <r v=\"2Cor.5.4\"></r>.†</s>"},"G1992":{"l":"ἐπιστολή","o":24,"ar":"<f><o>ἐπι-στολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>بلاغ، خبر</b>. </s> <s n=\"2.\"><b>رسالة، مكتوب</b>: <r v=\"Acts.9.2\"></r>، <r v=\"1Cor.5.9\"></r>، وفي مواضع أخرى؛ في الجمع، <r v=\"Acts.22.5\"></r>، <r v=\"1Cor.16.3\"></r>، وفي مواضع أخرى؛ <g>ἐ. σνστατικαί</g>، <r v=\"2Cor.3.1\"></r>.</s>","en":"<f><o>ἐπι-στολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιατέλλω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H107\">אִגֶּרֶת</h>, etc.; freq. in Mac ;]</e> </et> <s n=\"1.\"><b>a message</b>. </s> <s n=\"2.\"><b>a letter, an epistle</b>: <r v=\"Acts.9.2\"></r>, <r v=\"1Cor.5.9\"></r>, al.; pl., <r v=\"Acts.22.5\"></r>, <r v=\"1Cor.16.3\"></r>, al.; <g>ἐ. σνστατικαί</g>, <r v=\"2Cor.3.1\"></r> (cf. Milligan, <i>NTD</i>, 254 f.). (On the NT <g>ἐπιστολαί</g>, cf. Milligan, <i>Th.</i>, 121 ff.; <i>NTD</i>, 85 ff.; Deiss., <i>BS</i>, 3 ff.; <i>St. Paul</i>, 8 ff.)</s>"},"G1961":{"l":"ἐπιμένω","o":16,"ar":"<f><o>ἐπι-μένω </o></f> <s><b>مكث، تأنّى</b> أو <b>بقي بعدُ</b>: يليه <g>έν</g>: <r v=\"1Cor.16.8\"></r>؛ <g>αὐτοῦ</g>: هناك: <r v=\"Acts.15.34\"></r>، <r v=\"Acts.21.4\"></r>؛ مع القابل، <g>τ. σαρκί</g>: <r v=\"Phil.1.24\"></r>؛ يليه <g>παρά</g> مع قابل الشخص: <r v=\"Acts.28.14\"></r>؛ <g>πρός</g> مع منصوب الشخص: <r v=\"1Cor.16.7\"></r>، <r v=\"Gal.1.18\"></r>؛ مع منصوب الزمان: <r v=\"Acts.10.48\"></r>، <r v=\"Acts.21.4\"></r>، <r v=\"Acts.21.10\"></r>، <r v=\"Acts.28.12\"></r>، <r v=\"Acts.28.14\"></r>، <r v=\"1Cor.16.7\"></r>. مجازيًا: <b>داوم، ثبت</b> في عمل أو حال: مع القابل، <g>τ. ἀμαρτίᾳ</g>: <r v=\"Rom.6.1\"></r>؛ <g>τ. ὰπιστίᾳ</g>: <r v=\"Rom.11.23\"></r>؛ <g>τ. πίστει</g>: <r v=\"Col.1.23\"></r>؛ <g>αὐτοῖς</g>: <r v=\"1Tim.4.16\"></r>؛ <g>τ. χρηστότητι</g>: <r v=\"Rom.11.22\"></r>؛ مع اسم الفاعل: <r v=\"John.8.7\"></r>، <r v=\"Acts.12.16\"></r>.†</s>","en":"<f><o>ἐπι-μένω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.12.39\"></r> (<h n=\"H4102\">מָהַהּ</h> hith.)* ;] </e> </et> <s><b>to stay on, tarry</b> or <b>abide still</b>: seq. <g>έν</g>, <r v=\"1Cor.16.8\"></r>; <g>αὐτοῦ</g>, there, <r v=\"Acts.15.34\"></r> (WH, txt., RV, txt., omit) <r v=\"Acts.21.4\"></r>; c. dat., <g>τ. σαρκί</g>, <r v=\"Phil.1.24\"></r>; seq. <g>παρά</g>, c. dat. pers., <r v=\"Acts.28.14\"></r>; <g>πρός</g>, c. acc pers., <r v=\"1Cor.16.7\"></r>, <r v=\"Gal.1.18\"></r>; c. acc temp., <r v=\"Acts.10.48\"></r> <r v=\"Acts.21.4\"></r>, <r v=\"Acts.21.10\"></r> <r v=\"Acts.28.12\"></r>, <r v=\"Acts.28.14\"></r>, <r v=\"1Cor.16.7\"></r>. Metaph., <b>to continue</b> in a pursuit or state: c. dat., <g>τ. ἀμαρτίᾳ</g>, <r v=\"Rom.6.1\"></r>; <g>τ. ὰπιστίᾳ</g>, <r v=\"Rom.11.23\"></r>; <g>τ. πίστει</g>, <r v=\"Col.1.23\"></r>; <g>αὐτοῖς</g> (v. <i>CGT</i>, in l), <r v=\"1Tim.4.16\"></r>; <g>τ. χρηστότητι</g>, <r v=\"Rom.11.22\"></r>; c. ptcp. (cf. Bl., § 73, 4; 76, 2), <r v=\"John.8.7\"></r>, <r v=\"Acts.12.16\"></r>.†</s>"},"G1994":{"l":"ἐπιστρέφω","o":36,"ar":"<f><o>ἐπι-στρέφω </o></f> <s n=\"1.\">متعدٍّ: <b>أدار، حوّل</b> أو <b>وجّه نحو</b>، ومن ثمّ مجازيًا: <b>ردّ، أرجع</b> (إلى الله، إلى الفضيلة إلخ): <r v=\"Luke.1.16\"></r>، <r v=\"Luke.1.17\"></r> (قارن <r v=\"Mal.3.24\"></r>)، <r v=\"Jas.5.19\"></r>، <r v=\"Jas.5.20\"></r>. </s> <s n=\"2.\">لازم: </s> <s n=\"(a)\"><b>التفت، استدار</b>: <r v=\"Acts.16.18\"></r>؛ مع المصدر، <r v=\"Rev.1.12\"></r>؛ يليه <g>πρός</g>، <r v=\"Acts.9.40\"></r>؛ وكذلك المبني للمجهول، <r v=\"Mark.5.30\"></r>، <r v=\"Mark.8.33\"></r>، <r v=\"John.21.20\"></r>؛ مجازيًا، عن الرجوع إلى الله، <g>ἐπὶ τ. κύριον</g> (<g>θεόν</g>)، <r v=\"Acts.9.35\"></r>، <r v=\"Acts.11.21\"></r>، <r v=\"Acts.14.15\"></r>، <r v=\"Acts.15.19\"></r>، <r v=\"Acts.26.20\"></r>؛ <g>πρὸς τ. θεόν</g>، <r v=\"1Thess.1.9\"></r>، <r v=\"2Cor.3.16\"></r>؛ <g>ἀπὸ σκότους εἰς φῶς</g>، <r v=\"Acts.26.18\"></r>؛ المبني للمجهول، <r v=\"1Pet.2.25\"></r>؛ </s> <s n=\"(b)\"><b>رجع</b>: <r v=\"Luke.8.55\"></r>، <r v=\"Acts.15.36\"></r>؛ يليه <g>ὀπίσω</g> مع المصدر، <r v=\"Matt.24.18\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.12.44\"></r>، <r v=\"Mark.13.16\"></r>، <r v=\"Luke.2.39\"></r>، <r v=\"Luke.17.31\"></r>؛ <g>ἐπί</g>، <r v=\"2Pet.2.22\"></r>؛ مجازيًا، يليه <g>ἐπί</g>، <r v=\"Gal.4.9\"></r>؛ <g>πρός</g>، <r v=\"Luke.17.4\"></r>؛ عن الإصلاح الأخلاقي (الرجوع، التوبة)، <r v=\"Matt.13.15\"></r>، <r v=\"Mark.4.12\"></r>، <r v=\"Luke.22.32\"></r>، <r v=\"Acts.3.19\"></r>، <r v=\"Acts.28.27\"></r>؛ المبني للمجهول، <r v=\"Matt.10.13\"></r>.†</s>","en":"<f><o>ἐπι-στρέφω </o></f> <et> <e t=\"septuagint\">[very freq. in LXX, chiefly for <h n=\"H7725\">שׁוּב</h>, in its various senses, also for <h n=\"H6437\">פָּנָה</h>, etc. ;]</e> </et> <s n=\"1.\">trans., <b>to turn about, round</b> or <b>towards</b>, hence metaph., <b>to turn, cause to return</b> (to God, virtue, etc.): <r v=\"Luke.1.16\"></r>, <r v=\"Luke.1.17\"></r> (cf. <r v=\"Mal.3.24\"></r>), <r v=\"Jas.5.19\"></r>, <r v=\"Jas.5.20\"></r>. </s> <s n=\"2.\">Intrans., </s> <s n=\"(a)\"><b>to turn, turn oneself around</b>: <r v=\"Acts.16.18\"></r>; c. inf., <r v=\"Rev.1.12\"></r>; seq. <g>πρός</g>, <r v=\"Acts.9.40\"></r>; so also pass. (cl.), <r v=\"Mark.5.30\"></r> <r v=\"Mark.8.33\"></r>, <r v=\"John.21.20\"></r>; metaph., of turning to God (v. Field, <i>Notes</i>, 246 ff.), <g>ἐπὶ τ. κύριον</g> (<g>θεόν</g>), <r v=\"Acts.9.35\"></r> <r v=\"Acts.11.21\"></r> <r v=\"Acts.14.15\"></r> <r v=\"Acts.15.19\"></r> <r v=\"Acts.26.20\"></r>; <g>πρὸς τ. θεόν</g>, <r v=\"1Thess.1.9\"></r>, <r v=\"2Cor.3.16\"></r>; <g>ἀπὸ σκότους εἰς φῶς</g>, <r v=\"Acts.26.18\"></r>; pass., <r v=\"1Pet.2.25\"></r>; </s> <s n=\"(b)\"><b>to return</b> (as in MGr.): <r v=\"Luke.8.55\"></r>, <r v=\"Acts.15.36\"></r>; seq. <g>ὀπίσω</g>, c. inf., <r v=\"Matt.24.18\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.12.44\"></r>, <r v=\"Mark.13.16\"></r>, <r v=\"Luke.2.39\"></r> <r v=\"Luke.17.31\"></r>; <g>ἐπί</g>, <r v=\"2Pet.2.22\"></r>; metaph., seq. <g>ἐπί</g>, <r v=\"Gal.4.9\"></r>; <g>πρός</g>, <r v=\"Luke.17.4\"></r>; of moral reform, <r v=\"Matt.13.15\"></r>, <r v=\"Mark.4.12\"></r>, <r v=\"Luke.22.32\"></r>, <r v=\"Acts.3.19\"></r> <r v=\"Acts.28.27\"></r>; pass., <r v=\"Matt.10.13\"></r> (Cremer, 531, 881).†</s>"},"G1937":{"l":"ἐπιθυμέω","o":16,"ar":"<f><o>ἐπιθυμέω</o>، <g>-ῶ</g></f> <s><b>اشتهى، رغب في، اشتاق إلى، طمع في</b>: مطلقًا، <r v=\"Jas.4.2\"></r>، <r v=\"Rom.7.7\"></r>، <r v=\"Rom.13.9\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.10.6\"></r> (قارن <r v=\"4Macc.2.6\"></r>)؛ يليه <g>κατά </g> (ضدّ، في مقاومة)، <r v=\"Gal.5.17\"></r>؛ أصلاً مع المضاف إليه، <r v=\"Acts.20.33\"></r>، <r v=\"1Tim.3.1\"></r>؛ وفي اليونانية المتأخرة أيضًا مع المنصوب، <r v=\"Matt.5.28\"></r> (قارن <r v=\"Exod.20.17\"></r>، <r v=\"Mic.2.2\"></r>، <r v=\"Wis.16.3\"></r>، وفي مواضع أخرى)؛ مع المصدر، <r v=\"Matt.13.17\"></r>، <r v=\"Luke.15.16\"></r>، <r v=\"Luke.16.21\"></r>، <r v=\"Luke.17.22\"></r>، <r v=\"1Pet.1.12\"></r>، <r v=\"Rev.9.6\"></r>؛ مع المنصوب والمصدر، <r v=\"Heb.6.11\"></r>؛ كما في العبرية، <g>ἐπιθυμία ἐπεθύμησα</g>، <r v=\"Luke.22.15\"></r>.†</s>","en":"<f><o>ἐπιθυμέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>θυμός</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H183\">אָוָה</h> pi., hithp.; also for <h n=\"H2530\">חָמַד</h>, etc. ;] </e> </et> <s><b>to set one's heart upon, desire, lust after, covet</b>: absol., <r v=\"Jas.4.2\"></r>, <r v=\"Rom.7.7\"></r> <r v=\"Rom.13.9\"></r> <i>(LXX)</i>, <r v=\"1Cor.10.6\"></r> (of. <r v=\"4Macc.2.6\"></r>); seq. <g>κατά </g>(against, in opposition to), <r v=\"Gal.5.17\"></r>; prop. (as in cl.) c. gen., <r v=\"Acts.20.33\"></r>, <r v=\"1Tim.3.1\"></r>; in late Gk. also c. acc (M, <i>Pr.</i>, 65), <r v=\"Matt.5.28\"></r> (Rec. <g>αὐτῆς</g>; T omits; cf. <r v=\"Exod.20.17\"></r>, <r v=\"Mic.2.2\"></r>, <r v=\"Wis.16.3\"></r>, al.); c. inf., <r v=\"Matt.13.17\"></r>, <r v=\"Luke.15.16\"></r> <r v=\"Luke.16.21\"></r> <r v=\"Luke.17.22\"></r>, <r v=\"1Pet.1.12\"></r>, <r v=\"Rev.9.6\"></r>; c. acc et inf., <r v=\"Heb.6.11\"></r>; as in Hebrew, <g>ἐπιθυμία ἐπεθύμησα</g>, <r v=\"Luke.22.15\"></r>.†</s> <sy><i>SYN.</i>: <g>ὀρέγω</g> (cf. Field, <i>Notes</i>, 204), <g>θέλω</g> (<i>DCG</i>. i, 453<i>a</i>) </sy>"},"G1968":{"l":"ἐπιπίπτω","o":11,"ar":"<f><o>ἐπι-πίπτω </o></f> <s><b>وقع على</b>: مع قابل الشخص، <r v=\"Mark.3.10\"></r>، <r v=\"Acts.20.10\"></r>؛ يليه <g>ἐπὶ τ. τράχηλον</g> (كما في <r v=\"Gen.46.29\"></r>، <r v=\"Tob.11.8\"></r>، <r v=\"3Macc.5.49\"></r>، وفي مواضع أخرى)، <r v=\"Luke.15.20\"></r>، <r v=\"Acts.20.37\"></r>. مجازيًا، <g>φόβος</g>، <r v=\"Luke.1.12\"></r>، <r v=\"Acts.19.17\"></r>، <r v=\"Rev.11.11\"></r>؛ <g>ὀνειδισμοί</g>، <r v=\"Rom.15.3\"></r> <i>(السبعينية)</i>؛ عن الروح القدس: يليه <g>ἐπί</g> مع القابل، <r v=\"Acts.8.16\"></r>؛ <g>ἐπί</g> مع المنصوب، <r v=\"Acts.10.44\"></r>، <r v=\"Acts.11.15\"></r>؛ مطلقًا، <r v=\"Acts.23.7\"></r>.†</s>","en":"<f><o>ἐπι-πίπτω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5307\">נָפַל</h> ;] </e> </et> <s><b>to fall upon</b> (Field, <i>Notes</i>, 25): c. dat. pers., <r v=\"Mark.3.10\"></r> (v. Swete, in l), <r v=\"Acts.20.10\"></r>; seq. <g>ἐπὶ τ. τράχηλον</g> (as <r v=\"Gen.46.29\"></r>, <r v=\"Tob.11.8\"></r>, <r v=\"3Macc.5.49\"></r>, al.), <r v=\"Luke.15.20\"></r>, <r v=\"Acts.20.37\"></r>. Metaph., <g>φόβος</g>, <r v=\"Luke.1.12\"></r>, <r v=\"Acts.19.17\"></r>, <r v=\"Rev.11.11\"></r>; <g>ὀνειδισμοί</g>, <r v=\"Rom.15.3\"></r> <i>(LXX)</i>; of the Holy Spirit: seq. <g>ἐπί</g>, c. dat., <r v=\"Acts.8.16\"></r>; <g>ἐπί</g>, c. acc, <r v=\"Acts.10.44\"></r> <r v=\"Acts.11.15\"></r>; absol., <r v=\"Acts.23.7\"></r>.†</s>"},"G1971":{"l":"ἐπιποθέω","o":9,"ar":"<f><o>ἐπι-ποθέω</o>، <g>-ῶ </g></f> <s><b>اشتاق إلى، تاق إلى</b>: مع المصدر، <r v=\"Rom.1.11\"></r>، <r v=\"2Cor.5.2\"></r>، <r v=\"1Thess.3.6\"></r>، <r v=\"2Tim.1.4\"></r>، <r v=\"Phil.2.26\"></r>؛ مع منصوب الشيء، <r v=\"1Pet.2.2\"></r>؛ مع منصوب الشخص، <r v=\"2Cor.9.14\"></r>، <r v=\"Phil.1.8\"></r>، <r v=\"Phil.2.26\"></r>؛ مطلقًا، <r v=\"Jas.4.5\"></r>.†</s>","en":"<f><o>ἐπι-ποθέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2968\">יָאַב</h>, <h n=\"H707\">אָרַג</h>, <h n=\"H3700\">כָּסַף</h> hi., etc. ;] </e> </et> <s><b>to long for, desire</b>: c. inf., <r v=\"Rom.1.11\"></r>, <r v=\"2Cor.5.2\"></r>, <r v=\"1Thess.3.6\"></r>, <r v=\"2Tim.1.4\"></r>, <r v=\"Phil.2.26\"></r> (WH, [txt.]); c. acc rei, <r v=\"1Pet.2.2\"></r>; c. acc pers., <r v=\"2Cor.9.14\"></r>, <r v=\"Phil.1.8\"></r> <r v=\"Phil.2.26\"></r> (WH, mg); absol., <r v=\"Jas.4.5\"></r> (v. Mayor, in l.).†</s>"},"G1993":{"l":"ἐπιστομίζω","o":1,"ar":"<f>* <o>ἐπι-στομίζω</o></f> <s><b>ألجم</b>؛ مجازيًا: <b>سدّ الفم، أسكت</b>: <r v=\"Titus.1.11\"></r>.†</s>","en":"<f>* <o>ἐπι-στομίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>στόμα</g>), </e> </et> <s><b>to bridle</b>; metaph., <b>to stop the mouth, to silence</b>: <r v=\"Titus.1.11\"></r>.†</s>"},"G1905":{"l":"ἐπερωτάω","o":56,"ar":"<f><o>ἐπ-ερωτάω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>سأل، استشار، استفهم</b>: مع المنصوب للشخص، <r v=\"Mark.12.34\"></r>، <r v=\"Luke.2.46\"></r>، وفي مواضع أخرى؛ مع منصوبين، <r v=\"Mark.7.17\"></r> <r v=\"Mark.11.29\"></r>، <r v=\"Luke.20.40\"></r>، وفي مواضع أخرى؛ مع المنصوب للشخص، يليه <g>λέγων</g>، <r v=\"Matt.12.18\"></r>، <r v=\"Mark.9.11\"></r>؛ <g>εἰ</g>، <r v=\"Mark.8.23\"></r>، <r v=\"Luke.23.6\"></r>، وفي مواضع أخرى؛ <g>ἐ. θεόν</g>، <r v=\"Rom.10.20\"></r> <i>(السبعينية)</i>. </s> <s n=\"2.\">في اليونانية المتأخرة: <b>طلب من، التمس من</b>: مع المنصوب للشخص والمصدر، <r v=\"Matt.16.1\"></r> (قارن <g>ἐρωτάω</g>) </s>","en":"<f><o>ἐπ-ερωτάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7592\">שָׁאַל</h>, also for <h n=\"H1875\">דָּרַשׁ</h>, etc. ;]</e> </et> <s n=\"1.\"><b>to in­quire of, consult, question</b>: c. acc pers., <r v=\"Mark.12.34\"></r>, <r v=\"Luke.2.46\"></r>, al.; c. dupl. acc, <r v=\"Mark.7.17\"></r> <r v=\"Mark.11.29\"></r>, <r v=\"Luke.20.40\"></r>, al.; c. acc pers., seq. <g>λέγων</g>, <r v=\"Matt.12.18\"></r>, <r v=\"Mark.9.11\"></r>; <g>εἰ</g>, <r v=\"Mark.8.23\"></r>, <r v=\"Luke.23.6\"></r>, al.; <g>ἐ. θεόν</g>, <r v=\"Rom.10.20\"></r> <i>(LXX)</i>. </s> <s n=\"2.\">In late Gk., <b>to beg of, demand of</b>: c. acc pers. et inf., <r v=\"Matt.16.1\"></r> (cf. <g>ἐρωτάω</g>; and v. Cromer, 716) </s>"},"G1999":{"l":"ἐπισύστασις","o":7,"ar":"<f>† <o>ἐπι-σύστασις</o>، <g>-εως, ἡ</g></f> <s><b>تجمّع، حشد مشاغب، تألّب</b>: (قراءة بعض النسخ بدل <g>ἐπίστασις</g>، انظره)، <r v=\"Acts.24.12\"></r>، <r v=\"2Cor.11.28\"></r>.†</s>","en":"<f>† <o>ἐπι-σύστασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπισυνίστημι</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Num.16.40\"></r> (<h n=\"H5712\">עֵדָה</h>) <r v=\"Num.26.9\"></r> (<h n=\"H5327\">נָצָה</h> hi.), <r v=\"1Esd.5.73\"></r> A* ;] </e> </et> <s><b>a gathering, a riotous throng</b>: Rec. (for <g>ἐπίστασις</g>, q.v.), <r v=\"Acts.24.12\"></r>, <r v=\"2Cor.11.28\"></r>.†</s>"},"G1985":{"l":"ἐπίσκοπος","o":5,"ar":"<f><o>ἐπί-σκοπος</o>، <g>-ου, ὁ</g></f> <s><b>ناظر، حارس، رقيب</b>: <r v=\"Acts.20.28\"></r>، <r v=\"1Pet.2.25\"></r>؛ مصطلحًا فنيًا لوظيفة دينية، في رسائل بولس المتأخرة عن رئيس الكنيسة، <b>أسقف</b>: <r v=\"Phil.1.1\"></r>، <r v=\"1Tim.3.2\"></r>، <r v=\"Titus.1.7\"></r> (انظر تحت المدخل <g>ἐπισκοπή</g>).†</s>","en":"<f><o>ἐπί-σκοπος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>σκοπός</g>, <b>a watcher</b>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H6485\">פָּקַד</h>, its parts and derivatives, <r v=\"Num.4.16\"></r> <r v=\"Num.31.14\"></r>, <r v=\"Judg.9.28\"></r>, <r v=\"2Kgs.11.15\"></r>, <r v=\"2Kgs.11.18\"></r>, <r v=\"2Chr.34.12\"></r>, <r v=\"2Chr.34.17\"></r>, <r v=\"Neh.11.9\"></r>, <r v=\"Neh.11.14\"></r>, <r v=\"Neh.11.22\"></r>; <h n=\"H410\">אֵל</h>, <r v=\"Job.20.29\"></r>; <h n=\"H5065\">נוֹגַשׂ</h>:, <r v=\"Isa.60.17\"></r>; <r v=\"Wis.1.6\"></r>, <r v=\"1Macc.1.51\"></r> * ;] </e> </et> <s><b>a superintendent, guardian, overseer</b> (cl.; for exx. v. LS, s.v.): <r v=\"Acts.20.28\"></r>, <r v=\"1Pet.2.25\"></r> (<i>ICC</i>, in l.); as technical term for a religious office (Deiss., <i>BS</i>, 230 f.), in later Paul. epp. of the head of a church (Vg. <l>episcopus</l>), <b>a bishop</b>: <r v=\"Phil.1.1\"></r>, <r v=\"1Tim.3.2\"></r>, <r v=\"Titus.1.7\"></r> (v. reff. s.v. <g>ἐπισκοπή</g>).†</s>"},"G1936":{"l":"ἐπίθεσις","o":6,"ar":"<f><o>ἐπί-θεσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>وضع</b>: <g>χειρῶν</g>، <r v=\"Acts.8.18\"></r>، <r v=\"1Tim.4.14\"></r>، <r v=\"2Tim.1.6\"></r>، <r v=\"Heb.6.2\"></r> (قارن <r v=\"Heb.6.2\"></r>؛ <r v=\"1Tim.4.14\"></r>). </s> <s n=\"2.\">في السبعينية: <b>هجوم، اعتداء</b> (المكابيين الثاني).†</s>","en":"<f><o>ἐπί-θεσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιτίθημι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.25.27\"></r> (<h n=\"H7195\">קֶשֶׁר</h>), <r v=\"Ezek.23.11\"></r> (<h n=\"H5691\">עֲגָבָה</h>) <r v=\"2Macc.4.41\"></r> <r v=\"2Macc.5.5\"></r> <r v=\"2Macc.14.15\"></r> * ;] </e> </et> <s n=\"1.\"><b>a laying on</b>: <g>χειρῶν</g>, <r v=\"Acts.8.18\"></r>, <r v=\"1Tim.4.14\"></r>, <r v=\"2Tim.1.6\"></r>, <r v=\"Heb.6.2\"></r> (cf. Westc., <r v=\"Heb.6.2\"></r>; CGT on <r v=\"1Tim.4.14\"></r>). </s> <s n=\"2.\"><b>an attack, assault</b> (II Mac, ll.c.).†</s>"},"G1932":{"l":"ἐπιεικία","o":2,"ar":"<f><o>ἐπιεικία</o>، <g>-ας, ἡ</g> </f> <s><b>إنصاف، اعتدال، حِلم</b> («<b>التعقّل اللطيف</b>»): <r v=\"Acts.24.4\"></r>؛ مع <g>πραΰτης</g>، <r v=\"2Cor.10.1\"></r>.†</s>","en":"<f><o>ἐπιεικία</o> (Rec. <g>-είκεια</g>), <g>-ας, ἡ</g> </f> <et> <e t=\"derivation\">(&lt; <g>ἐπιεικής</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.2.19\"></r> <r v=\"Wis.12.18\"></r> <r v=\"Bar.2.27\"></r>, <r v=\"Dan.3.42\"></r>, <r v=\"Dan.4.24\"></r>, TH (3:42), <r v=\"2Macc.2.22\"></r> <r v=\"2Macc.10.4\"></r>, <r v=\"3Macc.3.15\"></r> <r v=\"3Macc.7.6\"></r> * ;]</e> </et> <s><b>fairness, moderation, gentleness</b> (\"<b>sweet reasonableness</b>,\" Matthew Arnold): <r v=\"Acts.24.4\"></r>; c. <g>πραΰτης</g>, <r v=\"2Cor.10.1\"></r>.†</s> <sy><i>SYN.</i>: <g>πραΰτης</g> (v. Tr., <i>Syn.</i>, § xliii)</sy>"},"G1901":{"l":"ἐπεκτείνω","o":1,"ar":"<f>* <o>ἐπ-εκ-τείνω </o></f> <s><b>مدّ</b>: الصيغة الوسطى، <b>امتدّ إلى قدّام</b>: مع القابل، <r v=\"Phil.3.13\"></r>.†</s>","en":"<f>* <o>ἐπ-εκ-τείνω </o></f> <s><b>to extend</b>: mid., <b>to stretch forward</b>: c. dat., <r v=\"Phil.3.13\"></r>.†</s>"},"G1973":{"l":"ἐπιπόθητος","o":1,"ar":"<f>*† <o>ἐπι-πόθητος</o>، <g>-ον </g></f> <s><b>مشتاق إليه، محبوب جدًّا</b>: <r v=\"Phil.4.1\"></r>.†</s>","en":"<f>*† <o>ἐπι-πόθητος</o>, <g>-ον </g></f> <s><b>greatly desired, longed for</b>: <r v=\"Phil.4.1\"></r>.†</s>"},"G1933":{"l":"ἐπιεικής","o":5,"ar":"<f><o>ἐπιεικής</o>، <g>-ές</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>لائق، مناسب</b>. </s> <s n=\"2.\"><b>منصف، حليم، معتدل، مترفّق</b>: <r v=\"1Tim.3.3\"></r>، <r v=\"Titus.3.2\"></r>، <r v=\"1Pet.2.18\"></r>، <r v=\"Jas.3.17\"></r>؛ <g>τὸ ἐ.</g> (الحِلم)، <r v=\"Phil.4.5\"></r> (قارن <r v=\"Jas.3.17\"></r>، وانظر تحت مدخل <g>ἐπιεικία</g>).†</s> <s><g>ἐπιείκεια</g>: انظر تحت مدخل <g>ἐπιεικία</g></s>","en":"<f><o>ἐπιεικής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>εἰκός</g>, <b>likely</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.86.5\"></r> (<h n=\"H5546\">סַלָּח</h>), <r v=\"Ezra.8.13\"></r> * ;] </e> </et> <s n=\"1.\"><b>seemly, fitting</b> (Hom.). </s> <s n=\"2.\"><b>equitable, fair, moderate</b>: <r v=\"1Tim.3.3\"></r>, <r v=\"Titus.3.2\"></r>, <r v=\"1Pet.2.18\"></r>, <r v=\"Jas.3.17\"></r>; <g>τὸ ἐ.</g> (Thuc., i, 76), <r v=\"Phil.4.5\"></r> (cf. Mayor, <r v=\"Jas.3.17\"></r>, and v.s. <g>ἐπιεικία</g>).†</s> <s><g>ἐπιείκεια</g> v.s. <g>ἐπιεικία</g></s>"},"G1935":{"l":"ἐπιθανάτιος","o":1,"ar":"<f>** <o>ἐπιθανάτιος</o>، <g>-ον </g></f> <s><b>محكوم عليه بالموت</b>: <r v=\"1Cor.4.9\"></r>.†</s>","en":"<f>** <o>ἐπιθανάτιος</o>, <g>-ον </g></f> <et> <e t=\"septuagint\">[in LXX: Da Bel <i>31</i> ;] </e> </et> <s><b>condemned to death</b>: <r v=\"1Cor.4.9\"></r>.†</s>"},"G1907":{"l":"ἐπέχω","o":5,"ar":"<f><o>ἐπ-έχω </o></f> <s n=\"1.\"><b>يمسك على، يضع على</b>. </s> <s n=\"2.\">مثل <g>παρέχω</g>: <b>يمدّ، يقدّم</b>: <g>λόγον ζωῆς</g>، <r v=\"Phil.2.16\"></r>. </s> <s n=\"3.\"><b>يوجّه</b> أو <b>يصوّب نحو</b>، أي <g>νοῦν</g>؛ </s> <s n=\"(a)\">مطلقًا: <b>يقصد، ينوي</b>؛ </s> <s n=\"(b)\"><b>يلاحظ، ينتبه إلى</b>: يليه <g>πῶς</g>، <r v=\"Luke.14.7\"></r>؛ مع القابل للشخص، <r v=\"Acts.3.5\"></r>، <r v=\"1Tim.4.16\"></r>. </s> <s n=\"4.\"><b>يمكث، ينتظر</b>: <r v=\"Acts.19.22\"></r> (في عبارة قانونية).†</s>","en":"<f><o>ἐπ-έχω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2308\">חָדַל</h>, etc.; also <r v=\"Sir.8.1\"></r> <r v=\"Sir.34.2\"></r>, <r v=\"2Macc.5.25\"></r> <r v=\"2Macc.9.25\"></r>, al. ;]</e> </et> <s n=\"1.\"><b>to hold upon</b>. </s> <s n=\"2.\">Like <g>παρέχω</g> (as in Hom., al.), <b>to hold out, offer</b>: <g>λόγον ζωῆς</g>, <r v=\"Phil.2.16\"></r>. </s> <s n=\"3.\"><b>to hold</b> or <b>direct towards</b>, Sc.<g>νοῦν</g>; </s> <s n=\"(a)\">absol., <b>to intend, purpose</b>; </s> <s n=\"(b)\"><b>to observe, give attention to</b> (v. MM, <i>Exp.</i>, xiv): seq. <g>πῶς</g>, <r v=\"Luke.14.7\"></r>; c. dat. pers., <r v=\"Acts.3.5\"></r>, <r v=\"1Tim.4.16\"></r>. </s> <s n=\"4.\"><b>to stay, wait</b>: <r v=\"Acts.19.22\"></r> (in legal phrase, MM, <i>Exp.</i>, l.c.).†</s>"},"G1934":{"l":"ἐπιζητέω","o":13,"ar":"<f><o>ἐπι-ζητέω</o>، <g>-ῶ </g></f> <s>صيغة «اتجاهية» من <g>ζητέω</g>، </s> <s><b>يسأل عن، يبحث عن، يرغب في</b>: مع المنصوب للشيء، <r v=\"Matt.6.32\"></r>، <r v=\"Matt.12.39\"></r>، <r v=\"Matt.16.4\"></r>، <r v=\"Luke.12.30\"></r>، <r v=\"Acts.19.39\"></r>، <r v=\"Rom.11.7\"></r>، <r v=\"Phil.4.17\"></r>، <r v=\"Heb.11.14\"></r>، <r v=\"Heb.13.14\"></r>؛ مع المنصوب للشخص، <r v=\"Luke.4.42\"></r>، <r v=\"Acts.12.19\"></r>؛ مع المصدر، <r v=\"Acts.13.7\"></r>.†</s>","en":"<f><o>ἐπι-ζητέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1875\">דָּרַשׁ</h>, <r v=\"2Kgs.8.8\"></r>, <r v=\"Isa.62.12\"></r>, al.; also for <h n=\"H1245\">בָּקַשׁ</h>, <r v=\"1Kgs.20.1\"></r>, <r v=\"Eccl.7.28\"></r>), <r v=\"Hos.3.5\"></r>; <h n=\"H6485\">פָּקַד</h>, <r v=\"2Kgs.3.8\"></r> ;] </e> </et> <s>\"directive\" of <g>ζητέω</g> (MM, <i>Exp.</i>, xiv), </s> <s><b>to inquire for, seek after, wish for</b>: c. acc rei, <r v=\"Matt.6.32\"></r> <r v=\"Matt.12.39\"></r> <r v=\"Matt.16.4\"></r>, <r v=\"Luke.12.30\"></r>, <r v=\"Acts.19.39\"></r>, <r v=\"Rom.11.7\"></r>, <r v=\"Phil.4.17\"></r>, <r v=\"Heb.11.14\"></r> <r v=\"Heb.13.14\"></r>; c. acc pers., <r v=\"Luke.4.42\"></r>, <r v=\"Acts.12.19\"></r>; c. inf., <r v=\"Acts.13.7\"></r>.†</s>"},"G1978":{"l":"ἐπίσημος","o":2,"ar":"<f><o>ἐπίσημος</o>، <g>-ον</g></f> <s n=\"1.\"><b>عليه علامة</b>؛ وعن النقود: <b>مختوم، مسكوك</b>. </s> <s n=\"2.\">مجازيًا، </s> <s n=\"(a)\">بالمعنى الحسن: <b>مشهور، لامع</b>: <r v=\"Rom.16.7\"></r>؛ </s> <s n=\"(b)\">بالمعنى السيئ: <b>سيّئ الصيت</b>: <r v=\"Matt.27.16\"></r>.†</s>","en":"<f><o>ἐπίσημος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>σῆμα</g>, <b>a mark</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.30.42\"></r> (<h n=\"H7194\">קָשַׁר</h>), <r v=\"Ezra.5.4\"></r> <r v=\"Ezra.8.13\"></r>, <r v=\"1Macc.11.37\"></r> <r v=\"1Macc.14.48\"></r>, <r v=\"2Macc.15.36\"></r>, <r v=\"3Macc.6.1\"></r> * ;]</e> </et> <s n=\"1.\"><b>bearing a mark</b>; of money, <b>stamped, coined</b>. </s> <s n=\"2.\">Metaph., </s> <s n=\"(a)\">in good sense, <b>notable, illustrious</b>: <r v=\"Rom.16.7\"></r>; </s> <s n=\"(b)\">in bad sense, <b>notorious</b>: <r v=\"Matt.27.16\"></r>.†</s>"},"G1949":{"l":"ἐπιλαμβάνω","o":19,"ar":"<f><o>ἐπι-λαμβάνω </o></f> <s>دائمًا بالصيغة الوسطى في السبعينية والعهد الجديد: <b>أمسك</b>، <b>أخذ بـ</b>: مع المضاف إليه للشخص: <r v=\"Matt.14.31\"></r>، <r v=\"Acts.17.19\"></r>، <r v=\"Acts.21.30\"></r>، <r v=\"Acts.21.33\"></r>؛ مع منصوب الشخص: <r v=\"Luke.9.47\"></r>، <r v=\"Luke.14.4\"></r>، <r v=\"Luke.23.26\"></r>، <r v=\"Acts.9.27\"></r>، <r v=\"Acts.16.9\"></r>، <r v=\"Acts.18.17\"></r>؛ مع المضاف إليه للشيء: <r v=\"Mark.8.23\"></r>، <r v=\"Acts.23.19\"></r>، <r v=\"Heb.8.9\"></r> <i>(السبعينية)</i>؛ مع المضاف إليه للشخص وللشيء: <r v=\"Luke.20.20\"></r>، <r v=\"Luke.20.26\"></r>؛ <g>τ. αἰωνίου</g> (<g>ὄντως</g>) <g>ζωῆς</g>: <r v=\"1Tim.6.12\"></r>، <r v=\"1Tim.6.19\"></r>. مجازيًا (كما في <r v=\"Sir.4.11\"></r>): <r v=\"Heb.2.16\"></r>.†</s>","en":"<f><o>ἐπι-λαμβάνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2388\">חָזַק</h> hi., <h n=\"H270\">אָחַז</h>, etc. ;] </e> </et> <s>always mid. in LXX and NT (v. Cremer, 758), <b>to lay hold of</b>: c. gen. pers., <r v=\"Matt.14.31\"></r>, <r v=\"Acts.17.19\"></r> <r v=\"Acts.21.30\"></r>, <r v=\"Acts.21.33\"></r>; c. acc pers. (not cl.), <r v=\"Luke.9.47\"></r> <r v=\"Luke.14.4\"></r> <r v=\"Luke.23.26\"></r> (WH, but v. Bl., 101<i>5</i>), <r v=\"Acts.9.27\"></r> <r v=\"Acts.16.9\"></r> <r v=\"Acts.18.17\"></r>; c. gen. rei, <r v=\"Mark.8.23\"></r>, <r v=\"Acts.23.19\"></r>, <r v=\"Heb.8.9\"></r> <i>(LXX)</i>; c. gen. pers. et rei, <r v=\"Luke.20.20\"></r>, <r v=\"Luke.20.26\"></r>; <g>τ. αἰωνίου</g> (<g>ὄντως</g>) <g>ζωῆς</g>, <r v=\"1Tim.6.12\"></r>, <r v=\"1Tim.6.19\"></r>. Metaph. (as in <r v=\"Sir.4.11\"></r>), <r v=\"Heb.2.16\"></r> (v. Westc., in l.).†</s>"},"G1944":{"l":"ἐπικατάρατος","o":2,"ar":"<f>† <o>ἐπι-κατ-άρατος</o>، <g>-ον</g></f> <s><b>ملعون</b>: <r v=\"Gal.3.10\"></r> <i>(السبعينية)</i>، <r v=\"Gal.3.13\"></r> <i>(السبعينية <g>κεκαταραμένος</g>)</i>.†</s>","en":"<f>† <o>ἐπι-κατ-άρατος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπικαταράομαι</g>, <b>to imprecate curses on</b>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H779\">אָרוּר</h>, also <r v=\"Wis.3.12\"></r> <r v=\"Wis.14.8\"></r>, <r v=\"4Macc.2.19\"></r> ;] </e> </et> <s><b>accursed</b>: <r v=\"Gal.3.10\"></r> <i>(LXX)</i> <r v=\"Gal.3.13\"></r> <i>(LXX <g>κεκαταραμένος</g>)</i> (Cremer, 109).†</s>"},"G1987":{"l":"ἐπίσταμαι","o":14,"ar":"<f><o>ἐπίσταμαι</o></f> <s><b>يعرف، يعلم بـ، يفهم</b>: مع المنصوب للشخص، <r v=\"Acts.19.15\"></r>؛ مع اسم الفاعل، <r v=\"Acts.24.10\"></r>؛ مع المنصوب للشيء، <r v=\"Mark.14.68\"></r>، <r v=\"Acts.18.25\"></r>، <r v=\"1Tim.6.4\"></r>، <r v=\"Jas.4.14\"></r>، <r v=\"Jude.1.10\"></r>؛ يليه <g>περί</g>، <r v=\"Acts.26.26\"></r>؛ <g>ὅτι</g>، <r v=\"Acts.15.7\"></r> <r v=\"Acts.19.25\"></r> <r v=\"Acts.22.19\"></r>؛ <g>ὡς</g>، <r v=\"Acts.10.28\"></r>؛ <g>πῶς</g>، <r v=\"Acts.20.18\"></r>؛ <g>ποῦ</g>، <r v=\"Heb.11.8\"></r>.†</s> <s>مرادفات: <g>γινώσκω</g> (انظره)، <g>οἶδα</g> </s>","en":"<f><o>ἐπίσταμαι</o></f> <et> <e t=\"derivation\">(prob. an old mid, of <g>ἐφίστημι</g>, q.v.), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3045\">יָדַע</h> ;] </e> </et> <s><b>to know, know of, understand</b>: c. acc pers., <r v=\"Acts.19.15\"></r>; c. ptcp., <r v=\"Acts.24.10\"></r>; c. acc rei, <r v=\"Mark.14.68\"></r>, <r v=\"Acts.18.25\"></r>, <r v=\"1Tim.6.4\"></r>, <r v=\"Jas.4.14\"></r>, <r v=\"Jude.1.10\"></r>; seq. <g>περί</g>, <r v=\"Acts.26.26\"></r>; <g>ὅτι</g>, <r v=\"Acts.15.7\"></r> <r v=\"Acts.19.25\"></r> <r v=\"Acts.22.19\"></r>; <g>ὡς</g>, <r v=\"Acts.10.28\"></r>; <g>πῶς</g>, <r v=\"Acts.20.18\"></r>; <g>ποῦ</g>, <r v=\"Heb.11.8\"></r>.†</s> <s>SYN: <g>γινώσκω</g> (q.v.), <g>οἶδα</g> </s>"},"G1945":{"l":"ἐπικείμαι","o":11,"ar":"<f><o>ἐπι-κείμαι </o></f> <s><b>يوضع على، يرقد على</b>: <r v=\"John.21.9\"></r>؛ يليه <g>ἐπί</g> مع القابل، <r v=\"John.11.38\"></r>؛ مجازيًا، <r v=\"Heb.9.10\"></r>؛ <g>ἀνάγκη</g>، <r v=\"1Cor.9.16\"></r>؛ <g>χειμῶν</g>، <b>يهدّد، يشتدّ</b>: <r v=\"Acts.27.20\"></r>؛ عن الأشخاص، <b>يُلحّ على، يضغط على</b>: <r v=\"Luke.5.1\"></r> <r v=\"Luke.23.23\"></r>.†</s>","en":"<f><o>ἐπι-κείμαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.39.31\"></r> (<h n=\"H5414\">נָתַן</h>), <r v=\"Job.19.3\"></r> (<h n=\"H1970\">הָכַר</h> hi.) <r v=\"Job.21.27\"></r> (<h n=\"H2554\">חָמַס</h>), <r v=\"1Macc.6.57\"></r>, <r v=\"2Macc.1.21\"></r>, <r v=\"3Macc.1.22\"></r> * ;]</e> </et> <s><b>to be placed, lie on</b>: <r v=\"John.21.9\"></r>; seq. <g>ἐπί</g>, c. dat., <r v=\"John.11.38\"></r>; fig., <r v=\"Heb.9.10\"></r>; <g>ἀνάγκη</g>, <r v=\"1Cor.9.16\"></r>; <g>χειμῶν</g>, <b>to threaten, come on</b>: <r v=\"Acts.27.20\"></r>; of persons, <b>to press upon</b>: <r v=\"Luke.5.1\"></r> <r v=\"Luke.23.23\"></r>.†</s>"},"G1959":{"l":"ἐπιμελέομαι","o":3,"ar":"<f><o>ἐπι-μελέομαι</o>، <g>-οῦμαι </g></f> <s><b>يعتني بـ</b>: مع المضاف إليه، <r v=\"Luke.10.34\"></r>، <r v=\"Luke.10.35\"></r>، <r v=\"1Tim.3.5\"></r>.†</s>","en":"<f><o>ἐπι-μελέομαι</o>, <g>-οῦμαι </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.44.21\"></r> (<h n=\"H5869\">עֵיוַים</h> <h n=\"H7760\">שִׁים</h>) <r v=\"1Esd.6.27\"></r>, <r v=\"Prov.27.25\"></r>, <r v=\"Sir.30.25\"></r>, <r v=\"1Macc.11.37\"></r> * ;]</e> </et> <s><b>to take care of</b>: c. gen., <r v=\"Luke.10.34\"></r>, <r v=\"Luke.10.35\"></r>, <r v=\"1Tim.3.5\"></r>.†</s>"},"G1974":{"l":"ἐπιποθία","o":1,"ar":"<f><o>ἐπιποθία</o>، <g>-ας, ἡ</g> = <g>ἐπιπόθησις</g>، </f> <s><b>اشتياق</b>: <r v=\"Rom.15.23\"></r>.†</s>","en":"<f><o>ἐπιποθία</o> (WH, <g>-πόθεια</g>), <g>-ας, ἡ</g> = <g>ἐπιπόθησις</g>, </f> <s><b>longing</b>: <r v=\"Rom.15.23\"></r>.†</s>"},"G1943":{"l":"ἐπικαλύπτω","o":1,"ar":"<f><o>ἐπι-καλύπτω </o></f> <s><b>يغطّي، يستر</b>: مجازيًا، <r v=\"Rom.4.7\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἐπι-καλύπτω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3680\">כָּסָה</h>, etc. ;] </e> </et> <s><b>to cover over, cover up</b>: metaph., <r v=\"Rom.4.7\"></r> <i>(LXX)</i>.†</s>"},"G1969":{"l":"ἐπιπλήσσω","o":1,"ar":"<f>* <o>ἐπι-πλήσσω </o></f> <s n=\"1.\"><b>ضرب، عاقب</b>. </s> <s n=\"2.\"><b>زجر، وبّخ</b>: <r v=\"1Tim.5.1\"></r>.†</s>","en":"<f>* <o>ἐπι-πλήσσω </o></f> <s n=\"1.\"><b>to strike at, to punish</b>. </s> <s n=\"2.\"><b>to rebuke, reprove</b>: <r v=\"1Tim.5.1\"></r>.†</s>"},"G1950":{"l":"ἐπιλανθάνομαι","o":8,"ar":"<f><o>ἐπι-λανθάνομαι</o></f> <s><b>نسي، أهمل</b>: مع المصدر، <r v=\"Matt.16.5\"></r>، <r v=\"Mark.8.14\"></r>؛ مع المضاف إليه، <r v=\"Heb.6.10\"></r> <r v=\"Heb.13.2\"></r>، <r v=\"Heb.13.16\"></r>؛ مع المنصوب، <r v=\"Phil.3.13\"></r>؛ <g>ὁποῖος ἦν</g>، <r v=\"Jas.1.24\"></r>؛ واسم الفاعل المبني للمجهول (قارن <r v=\"Isa.23.16\"></r>، <r v=\"Sir.3.14\"></r> <r v=\"Sir.23.14\"></r>، <r v=\"Wis.2.4\"></r>)، <r v=\"Luke.12.6\"></r>.†</s>","en":"<f><o>ἐπι-λανθάνομαι</o></f> <et> <e t=\"derivation\">(alternative mid, form of <g>ἐπιλήθω</g>, <b>to cause to forget</b>) </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7911\">שָׁכַח</h> ;] </e> </et> <s><b>to forget, neglect</b>: c. inf., <r v=\"Matt.16.5\"></r>, <r v=\"Mark.8.14\"></r>; c. gen., <r v=\"Heb.6.10\"></r> <r v=\"Heb.13.2\"></r>, <r v=\"Heb.13.16\"></r>; c. acc (as occasionally in cl.; MM, <i>Exp.</i>, xiv), <r v=\"Phil.3.13\"></r>; <g>ὁποῖος ἦν</g>, <r v=\"Jas.1.24\"></r>; pass. ptcp. (cf. <r v=\"Isa.23.16\"></r>, <r v=\"Sir.3.14\"></r> <r v=\"Sir.23.14\"></r>, <r v=\"Wis.2.4\"></r>), <r v=\"Luke.12.6\"></r>.†</s>"},"G1912":{"l":"ἐπιβαρέω","o":3,"ar":"<f>† <o>ἐπι-βαρέω</o>، <g>-ῶ </g> </f> <s><b>ثقّل على، كان عبئًا</b>: مجازيًا، مطلقًا، <r v=\"2Cor.2.5\"></r>؛ مع منصوب الشخص، <r v=\"1Thess.2.9\"></r>، <r v=\"2Thess.3.8\"></r>.†</s>","en":"<f>† <o>ἐπι-βαρέω</o>, <g>-ῶ </g></f> <s><b>to put a burden on, be burdensome</b>: fig., absol., <r v=\"2Cor.2.5\"></r>; c. acc pers., <r v=\"1Thess.2.9\"></r>, <r v=\"2Thess.3.8\"></r> (cf. M, <i>Th.</i>, I, 2:9).†</s>"},"G1930":{"l":"ἐπιδιορθόω","o":1,"ar":"<f>*† <o>ἐπι-δι-ορθόω </o> </f> <s><b>أكمل الترتيب، رتّب ما بقي</b>: <r v=\"Titus.1.5\"></r>.† </s>","en":"<f>*† <o>ἐπι-δι-ορθόω </o></f> <s><b>to set in order further</b>: <r v=\"Titus.1.5\"></r> (Inscr.; Cremer, 808).† </s>"},"G1921":{"l":"ἐπιγινώσκω","o":44,"ar":"<f><o>ἐπι-γινώσκω </o></f> <s>صيغة \"توجيهية\" من <g>γινώσκω</g>؛ </s> <s n=\"1.\"><b>لاحظ، أدرك، ميّز، عرف (تعرّف على)</b>؛ </s> <s n=\"(a)\">مطلقًا: <r v=\"Acts.25.10\"></r>، <r v=\"1Cor.13.12\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Luke.1.22\"></r>؛ <g>τ. πνεύματι</g>، يليه <g>ὅτι</g>، <r v=\"Mark.2.8\"></r>؛ </s> <s n=\"(b)\">مع المنصوب للشيء: <r v=\"Luke.1.4\"></r> <r v=\"Luke.5.22\"></r>، <r v=\"Acts.12.14\"></r> <r v=\"Acts.27.39\"></r>، <r v=\"Rom.1.32\"></r>، <r v=\"2Cor.1.13\"></r>، <r v=\"Col.1.6\"></r>، <r v=\"1Tim.4.3\"></r>؛ <g>ἐν ἐαυτῷ</g>، <r v=\"Mark.5.30\"></r>؛ يليه <g>ὅτι</g>، <r v=\"1Cor.14.37\"></r>؛ </s> <s n=\"(c)\">مع المنصوب للشخص: <r v=\"Matt.11.27\"></r> <r v=\"Matt.14.35\"></r> <r v=\"Matt.17.12\"></r>، <r v=\"Mark.6.33\"></r>، <r v=\"Mark.6.54\"></r>، <r v=\"Luke.24.16\"></r>، <r v=\"Luke.24.31\"></r>، <r v=\"1Cor.16.18\"></r>، <r v=\"2Cor.1.14\"></r>؛ يليه <g>ἀπό</g> مع المضاف إليه للشيء، <r v=\"Matt.7.16\"></r>، <r v=\"Matt.7.20\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Acts.3.10\"></r> <r v=\"Acts.4.13\"></r>، <r v=\"2Cor.13.5\"></r>؛ المبني للمجهول، <r v=\"1Cor.13.12\"></r>؛ عكس <g>ἀγνοούμενοι</g>، <r v=\"2Cor.6.9\"></r>. </s> <s n=\"2.\"><b>اكتشف، تحقّق، تيقّن</b>: <r v=\"Acts.9.30\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Luke.7.37\"></r> <r v=\"Luke.23.7\"></r>، <r v=\"Acts.19.34\"></r> <r v=\"Acts.22.29\"></r> <r v=\"Acts.24.11\"></r> <r v=\"Acts.28.1\"></r>؛ مع المنصوب للشيء ويليه سؤال، <r v=\"Acts.23.28\"></r>؛ <g>δι’ ἣν αἰτίαν</g>، <r v=\"Acts.22.24\"></r>؛ <g>παρά</g> مع المضاف إليه للشخص، يليه <g>περί</g> مع المضاف إليه للشيء، <r v=\"Acts.24.8\"></r>؛ <g>τ. ὁδὸν τῆς δικαιοσύνης</g>، <r v=\"2Pet.2.21\"></r>.†</s>","en":"<f><o>ἐπι-γινώσκω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5234\">נָכַר</h>: hi., also for <h n=\"H3045\">יָדַע</h>, etc. ;] </e> </et> <s>\"directive\" of <g>γινώσκω</g> (AR, <i>Eph.</i>, 249), as in cl.; </s> <s n=\"1.\"><b>to observe, perceive, discern, recognize</b>; </s> <s n=\"(a)\">absol.: <r v=\"Acts.25.10\"></r>, <r v=\"1Cor.13.12\"></r>; seq. <g>ὅτι</g>, <r v=\"Luke.1.22\"></r>; <g>τ. πνεύματι</g>, seq. <g>ὅτι</g>, <r v=\"Mark.2.8\"></r>; </s> <s n=\"(b)\">c. acc rei: <r v=\"Luke.1.4\"></r> <r v=\"Luke.5.22\"></r>, <r v=\"Acts.12.14\"></r> <r v=\"Acts.27.39\"></r>, <r v=\"Rom.1.32\"></r>, <r v=\"2Cor.1.13\"></r>, <r v=\"Col.1.6\"></r>, <r v=\"1Tim.4.3\"></r>; <g>ἐν ἐαυτῷ</g>, <r v=\"Mark.5.30\"></r>; seq. <g>ὅτι</g>, <r v=\"1Cor.14.37\"></r>; </s> <s n=\"(c)\">c. acc pers.: <r v=\"Matt.11.27\"></r> <r v=\"Matt.14.35\"></r> <r v=\"Matt.17.12\"></r>, <r v=\"Mark.6.33\"></r> (T, <g>αὐτούς</g>, but LTr., WH, R, omit the pron., and LTr., WH, txt., read <g>ἔγνωσαν</g>), <r v=\"Mark.6.54\"></r>, <r v=\"Luke.24.16\"></r>, <r v=\"Luke.24.31\"></r>, <r v=\"1Cor.16.18\"></r>, <r v=\"2Cor.1.14\"></r>; seq. <g>ἀπό</g>, c. gen. rei, <r v=\"Matt.7.16\"></r>, <r v=\"Matt.7.20\"></r>; seq. <g>ὅτι</g>, <r v=\"Acts.3.10\"></r> <r v=\"Acts.4.13\"></r>, <r v=\"2Cor.13.5\"></r>; pass., <r v=\"1Cor.13.12\"></r>; opp. to <g>ἀγνοούμενοι</g>, <r v=\"2Cor.6.9\"></r>. </s> <s n=\"2.\"><b>to discover, ascertain, determine</b>: <r v=\"Acts.9.30\"></r>; seq. <g>ὅτι</g>, <r v=\"Luke.7.37\"></r> <r v=\"Luke.23.7\"></r>, <r v=\"Acts.19.34\"></r> <r v=\"Acts.22.29\"></r> <r v=\"Acts.24.11\"></r> <r v=\"Acts.28.1\"></r>; c. acc rei, seq. quæst., <r v=\"Acts.23.28\"></r>; <g>δι’ ἣν αἰτίαν</g>, <r v=\"Acts.22.24\"></r>; <g>παρά</g>, c. gen. pers., seq. <g>περί</g>, c. gen. rei, <r v=\"Acts.24.8\"></r>; <g>τ. ὁδὸν τῆς δικαιοσύνης</g>, <r v=\"2Pet.2.21\"></r> (cf. Lft., <i>Col</i>., 136; Cremer, 159; M, <i>Pr.</i>, 113; AR, <i>Eph.</i>, 248 ff.).†</s>"},"G1928":{"l":"ἐπιδιατάσσομαι","o":1,"ar":"<f>*† <o>ἐπι-δια-τάσσομαι </o></f> <s><b>أضاف بنودًا إلى</b> وثيقة: <r v=\"Gal.3.15\"></r> (قارن <g>ἐπιδιαθήκη</g>، <b>وصية ثانية</b>).†</s>","en":"<f>*† <o>ἐπι-δια-τάσσομαι </o></f> <s><b>to add provisions to</b> a document: <r v=\"Gal.3.15\"></r> (cf. <g>ἐπιδιαθήκη</g>, <b>a second will</b>, F1J, <i>BJ</i>, ii, 2, 3; the word is used of wills in <g>π.</g>, cf. Deiss., <i>LAE</i>, 87).†</s>"},"G1965":{"l":"ἐπίορκος","o":1,"ar":"<f><o>ἐπί-ορκος</o>، <g>-ον </g></f> <s n=\"1.\">عن القَسَم: <b>محلوف به كذبًا</b>. </s> <s n=\"2.\">عن الأشخاص: <b>حانث</b>؛ وبمعنى الاسم: <b>حانث، حالف بالزور</b>: <r v=\"1Tim.1.10\"></r>.†</s>","en":"<f><o>ἐπί-ορκος</o>, <g>-ον </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Zech.5.3\"></r> (<h n=\"H7650\">שָׁבַע</h> ni.) * ;] </e> </et> <s n=\"1.\">of oaths, <b>sworn falsely</b>. </s> <s n=\"2.\">Of persons, <b>perjured</b>; as subst., <b>a perjurer, false swearer</b>: <r v=\"1Tim.1.10\"></r>.†</s>"},"G1911":{"l":"ἐπιβάλλω","o":18,"ar":"<f><o>ἐπι-βάλλω </o></f> <s n=\"1.\">متعدٍّ، <b>يُلقي، يضع</b> أو <b>يجعل على</b>: مع المنصوب والقابل، <r v=\"Mark.11.7\"></r>، <r v=\"1Cor.7.35\"></r>؛ مع المنصوب، يليه <g>ἐπί</g> مع المنصوب، <r v=\"Rev.18.19\"></r>؛ <g>τ. Χεῖρα</g> (<g>-ας</g>) <g>ἐπί</g>، عن القبض على أسير، <r v=\"Matt.26.50\"></r>، <r v=\"Luke.20.19\"></r>، <r v=\"Luke.21.12\"></r>، <r v=\"John.7.30\"></r>، <r v=\"Acts.5.18\"></r>، <r v=\"Acts.21.27\"></r>؛ مع القابل، <r v=\"Mark.14.46\"></r>، <r v=\"Acts.4.3\"></r>؛ مع المصدر، <r v=\"Acts.12.1\"></r>؛ <g>τὴν χ. ἐπ’ ἄροτρον</g>، <r v=\"Luke.9.62\"></r>؛ <g>ἐπίβλημα ἐπὶ ἱμάτιον</g>، <r v=\"Luke.5.36\"></r>؛ <g>ἐπὶ ἱματίῳ</g>، <r v=\"Matt.9.16\"></r>. </s> <s n=\"2.\">لازم، </s> <s n=\"(a)\"><b>يندفع</b> أو <b>ينقضّ على</b>: <g>τ. κύματα εἰς τ. πλοῖον</g>، <r v=\"Mark.4.37\"></r>؛ مجازيًا، <b>يوجّه فكره إلى</b>: <g>ἐπιβαλὼν ἔκλαιεν</g>، <b>لما تفكّر به</b> (يُقدَّر <g>τ. ῥήματι</g>)، <b>بكى</b> (وفي هامش الترجمة المنقحة: <b>أخذ يبكي</b>): <r v=\"Mark.14.72\"></r>؛ </s> <s n=\"(b)\"><b>يقع من نصيب أحد</b>: <g>τὸ ἐπιβάλλον</g> (يُقدَّر القابل؛ صيغة اصطلاحية)، <r v=\"Luke.15.12\"></r>.†</s>","en":"<f><o>ἐπι-βάλλω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7971\">שָׁלַח</h>, <h n=\"H7896\">שִׁית</h>, etc. ;]</e> </et> <s n=\"1.\">trans., <b>to cast, lay</b> or <b>put upon</b>: c. acc et dat., <r v=\"Mark.11.7\"></r>, <r v=\"1Cor.7.35\"></r>; c. acc, seq. <g>ἐπί</g> c. acc, <r v=\"Rev.18.19\"></r>, WH, mg.; <g>τ. Χεῖρα</g> (<g>-ας</g>) <g>ἐπί</g> (B1., § 37, 7), of seizing a prisoner, <r v=\"Matt.26.50\"></r>, <r v=\"Luke.20.19\"></r> <r v=\"Luke.21.12\"></r>, <r v=\"John.7.30\"></r>, <r v=\"Acts.5.18\"></r> <r v=\"Acts.21.27\"></r>; c. dat. (Polyb.), <r v=\"Mark.14.46\"></r> <r v=\"Acts.4.3\"></r>; c. inf., <r v=\"Acts.12.1\"></r>; <g>τὴν χ. ἐπ’ ἄροτρον</g>, <r v=\"Luke.9.62\"></r>; <g>ἐπίβλημα ἐπὶ ἱμάτιον</g>, <r v=\"Luke.5.36\"></r>; <g>ἐπὶ ἱματίῳ</g>, <r v=\"Matt.9.16\"></r>. </s> <s n=\"2.\">Intrans., </s> <s n=\"(a)\"><b>to throw oneself</b> or <b>rush upon</b>: <g>τ. κύματα εἰς τ. πλοῖον</g>, <r v=\"Mark.4.37\"></r>; metaph., <b>to put one's mind upon</b> (but v. Field, <i>Notes</i>, 41 ff.), <g>ἐπιβαλὼν ἔκλαιεν</g>, <b>when he thought thereon</b> (sc. <g>τ. ῥήματι</g>), <b>he wept</b> (EV, txt.; R, mg., <b>he began to weep</b>; cf. M, <i>Pr.</i>, 131): <r v=\"Mark.14.72\"></r> (v. also Swete, in l); </s> <s n=\"(b)\"><b>to fall to one's share</b>: <g>τὸ ἐπιβάλλον</g> (sc. dat.; Hdt., a1., a technical formula freq. in <g>π.</g>; Deiss., BS, 230, <i>LAE</i>, 152), <r v=\"Luke.15.12\"></r>.†</s>"},"G1997":{"l":"ἐπισυναγωγή","o":2,"ar":"<f>**† <o>ἐπι-συν-αγωγή</o>، <g>-ῆς, ἡ</g></f> <s><b>اجتماع، جمع معًا</b>: <r v=\"Heb.10.25\"></r>؛ يليه <g>ἐπί</g>، <r v=\"2Thess.2.1\"></r> (قارن <r v=\"2Macc.2.7\"></r>).†</s>","en":"<f>**† <o>ἐπι-συν-αγωγή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπισυνάγω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.2.7\"></r> * ;] </e> </et> <s><b>a gathering together, assembly</b>: <r v=\"Heb.10.25\"></r>; seq. <g>ἐπί</g>, <r v=\"2Thess.2.1\"></r> (cf. <r v=\"2Macc.2.7\"></r>).†</s>"},"G1986":{"l":"ἐπισπάω","o":1,"ar":"<f><o>ἐπι-σπάω</o>، <g>-ῶ </g></f> <s><b>يجذب على، يسحب فوق</b>: الصيغة الوسطى، بمعنى خاص هو إزالة علامات الختان اليهودي (قارن <r v=\"1Macc.1.15\"></r>)، <b>يصير كأنه أغلف</b>: <r v=\"1Cor.7.18\"></r>.†</s>","en":"<f><o>ἐπι-σπάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.5.18\"></r> (<h n=\"H4900\">מָשַׁךְ</h>), etc. ;]</e> </et> <s><b>to draw on</b>: mid., in peculiar sense of effacing signs of Judaism (cf. <r v=\"1Macc.1.15\"></r>, FlJ, <i>Ant.</i>, xii, 5, i; v. Thayer, s.v.), <b>to become as uncircumcised</b>: <r v=\"1Cor.7.18\"></r>.†</s>"},"G1984":{"l":"ἐπισκοπή","o":4,"ar":"<f>† <o>ἐπι-σκοπή</o>، <g>-ῆς, ἡ </g></f> <s n=\"1.\"><b>افتقاد، زيارة</b>؛ وكما في السبعينية (على نمط العبرية)، عن افتقاد الله بالرحمة أو بالقضاء (<r v=\"Lev.19.20\"></r> <r v=\"Job.10.12\"></r>، <r v=\"Jer.6.15\"></r>، <r v=\"Wis.2.20\"></r>، وفي مواضع أخرى): <r v=\"Luke.19.44\"></r>، <r v=\"1Pet.2.12\"></r>. </s> <s n=\"2.\"><b>وظيفة، مسؤولية</b>، خاصةً <b>وظيفة</b> <g>ἐπίσκοιος</g> (أي الأسقف، انظره): <r v=\"Acts.1.20\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.3.1\"></r>.†</s>","en":"<f>† <o>ἐπι-σκοπή</o>, <g>-ῆς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiey for <h n=\"H6485\">פָּקַד</h> <h n=\"H6486\">פְּקֻדָּה</h> ;] </e> </et> <s n=\"1.\"><b>a visiting, visitation</b> (<g>εἰς ἐ. τοῦ παιδός</g>, Lucian, dial. deor., 20, 6); as in LXX (after Heb.), of God's visitation in mercy, or in judgment (<r v=\"Lev.19.20\"></r> <r v=\"Job.10.12\"></r>, <r v=\"Jer.6.15\"></r>, <r v=\"Wis.2.20\"></r>, al.): <r v=\"Luke.19.44\"></r>, <r v=\"1Pet.2.12\"></r> (v. Hort, in l.). </s> <s n=\"2.\"><b>office, charge</b>, esp. <b>office of an</b> <g>ἐπίσκοιος</g> (q.v.): <r v=\"Acts.1.20\"></r> <i>(LXX)</i>, <r v=\"1Tim.3.1\"></r> (Cremer, 527 f., 864; <i>DCG</i>, ii, 809 <i>b</i>).†</s>"},"G1919":{"l":"ἐπίγειος","o":7,"ar":"<f>* <o>ἐπί-γειος</o>، <g>-ον</g></f> <s><b>أرضي، من الأرض</b>: <g>τὰ ἐ.</g> (الأرضيات)، <r v=\"John.3.12\"></r> <r v=\"Phil.2.10\"></r> <r v=\"Phil.3.19\"></r> (بدون أداة التعريف)؛ <g>σώματα</g> (أجسام)، <r v=\"1Cor.15.40\"></r>؛ <g>οἰκία</g> (بيت)، <r v=\"2Cor.5.1\"></r>؛ <g>σοφία</g> (حكمة)، <r v=\"Jas.3.15\"></r>.†</s>","en":"<f>* <o>ἐπί-γειος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπί</g>, <g>γῆ</g>), </e> </et> <s><b>of the earth, earthly</b>: <g>τὰ ἐ.</g>, <r v=\"John.3.12\"></r> <r v=\"Phil.2.10\"></r> <r v=\"Phil.3.19\"></r> (anarth.); <g>σώματα</g>, <r v=\"1Cor.15.40\"></r>; <g>οἰκία</g>, <r v=\"2Cor.5.1\"></r>; <g>σοφία</g>, <r v=\"Jas.3.15\"></r> (Cremer, 153).†</s>"},"G1981":{"l":"ἐπισκηνόω","o":1,"ar":"<f>*† <o>ἐπι-σκηνόω</o>، <g>-ῶ </g></f> <s><b>نصب خيمة فوق، ظلّل كمسكن</b>: مجازيًا، يليه <g>ἐπ’ ἐμέ</g> (الترجمة المنقحة: <b>تحلّ عليّ، تظلّلني</b>)، <r v=\"2Cor.12.9\"></r>.†</s>","en":"<f>*† <o>ἐπι-σκηνόω</o>, <g>-ῶ </g></f> <s><b>to tent upon, spread a tabernacle over</b>: metaph., seq. <g>ἐπ’ ἐμέ</g> (RV,<b> rest upon, cover</b>), <r v=\"2Cor.12.9\"></r>.†</s>"},"G1938":{"l":"ἐπιθυμητής","o":1,"ar":"<f><o>ἐπιθυμητής</o>، <g>-οῦ, ὁ</g></f> <s><b>مشتهٍ، راغب في</b>: <g>κακῶν</g> (شرور)، <r v=\"1Cor.10.6\"></r>.†</s>","en":"<f><o>ἐπιθυμητής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιθυμέω</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Num.11.34\"></r> (<h n=\"H183\">אָוָה</h> hithp.); <g>εἶναι ἐ.</g>, <r v=\"Prov.1.22\"></r> (<h n=\"H2530\">חָמַד</h>)* ;] </e> </et> <s><b>one longing for, lustful after</b>: <g>κακῶν</g>, <r v=\"1Cor.10.6\"></r>.†</s>"},"G1908":{"l":"ἐπηρεάζω","o":2,"ar":"<f>* <o>ἐπηρεάζω</o></f> <s><b>أساء إلى، شتم</b>: مع المنصوب للشخص، <r v=\"Luke.6.28\"></r>؛ مع منصوب الشيء، <r v=\"1Pet.3.16\"></r>.†</s>","en":"<f>* <o>ἐπηρεάζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ἐπήρεια</g>, <b>spiteful abuse</b>), </e> </et> <s><b>to revile</b>: c. acc pers., <r v=\"Luke.6.28\"></r>; c. acc rei (but v. <i>ICC</i>, in l.), <r v=\"1Pet.3.16\"></r>.†</s>"},"G1914":{"l":"ἐπιβλέπω","o":3,"ar":"<f><o>ἐπι-βλέπω </o></f> <s><b>نظر إلى</b>. وفي العهد الجديد، كما في السبعينية (<r v=\"1Sam.1.11\"></r> <r v=\"1Sam.9.16\"></r>، <r v=\"Ps.25.16\"></r>؛ <r v=\"Tob.3.3\"></r>، وفي مواضع أخرى): <b>نظر بعين الرضا</b>: يليه <g>ἐπί</g> مع منصوب الشخص، <r v=\"Luke.1.48\"></r> <r v=\"Luke.9.38\"></r>، <r v=\"Jas.2.3\"></r>.†</s>","en":"<f><o>ἐπι-βλέπω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5027\">נָבַט</h> hi., <h n=\"H6437\">פָּנָה</h>, <h n=\"H7200\">רָאָה</h>, etc. ;] </e> </et> <s><b>to look upon</b>. In NT, as in LXX (<r v=\"1Sam.1.11\"></r> <r v=\"1Sam.9.16\"></r>, <r v=\"Ps.25.16\"></r>; <r v=\"Tob.3.3\"></r>, al.), <b>to look on with favour</b>: seq. <g>ἐπί</g> c. acc pers., <r v=\"Luke.1.48\"></r> <r v=\"Luke.9.38\"></r>, <r v=\"Jas.2.3\"></r>.†</s>"},"G1924":{"l":"ἐπιγράφω","o":5,"ar":"<f><o>ἐπι-γράφω </o></f> <s><b>كتب على، نقش</b>: <r v=\"Mark.15.26\"></r>، <r v=\"Acts.17.23\"></r>، <r v=\"Rev.21.12\"></r>؛ مجازيًا، <r v=\"Heb.8.10\"></r> <i>(السبعينية)</i> <r v=\"Heb.10.16\"></r> <i>(كذلك)</i>.†</s>","en":"<f><o>ἐπι-γράφω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3789\">כָּתַב</h>, <r v=\"Num.17.2\"></r>; fig., <r v=\"Jer.31.33\"></r>, al. ;] </e> </et> <s><b>to write upon, inscribe</b>: <r v=\"Mark.15.26\"></r>, <r v=\"Acts.17.23\"></r>, <r v=\"Rev.21.12\"></r>; fig., <r v=\"Heb.8.10\"></r> <i>(LXX)</i> <r v=\"Heb.10.16\"></r> <i>(ib)</i>.†</s>"},"G1955":{"l":"ἐπίλυσις","o":1,"ar":"<f>** <o>ἐπί-λυσις -εως</o>، <g>ἡ</g></f> <s n=\"1.\"><b>حَلّ، إطلاق</b>. </s> <s n=\"2.\"><b>حلّ، تفسير</b>: <r v=\"2Pet.1.20\"></r>.†</s>","en":"<f>** <o>ἐπί-λυσις -εως</o>, <g>ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιλύω</g>), </e> <e t=\"septuagint\">[in Aq.: <r v=\"Gen.40.8\"></r>; Sm.: <r v=\"Hos.3.4\"></r> * ;] </e> </et> <s n=\"1.\"><b>release</b>. </s> <s n=\"2.\"><b>solution, interpretation</b>: <r v=\"2Pet.1.20\"></r>.†</s>"},"G1980":{"l":"ἐπισκέπτομαι","o":11,"ar":"<f><o>ἐπι-σκέπτομαι</o></f> <s n=\"1.\"><b>فحص، تفقّد</b>. </s> <s n=\"2.\">(a) <b>زار، افتقد</b>: مع المنصوب، <r v=\"Acts.7.23\"></r> <r v=\"Acts.15.36\"></r> (قارن <r v=\"Judg.15.1\"></r>)؛ خاصةً المرضى والمتضايقين، <r v=\"Matt.25.36\"></r>، <r v=\"Matt.25.43\"></r>، <r v=\"Jas.1.27\"></r> (قارن <r v=\"Sir.7.35\"></r>)؛ </s> <s n=\"(b)\">في السبعينية والعهد الجديد (مثل <h n=\"H6485\">פָּקַד</h> في <r v=\"Gen.21.1\"></r>، <r v=\"Exod.4.31\"></r>، <r v=\"Ps.8.5\"></r>، وفي مواضع أخرى)، <b>افتقد بالعون، اعتنى بـ</b>: <r v=\"Luke.1.68\"></r>، <r v=\"Luke.1.78\"></r> <r v=\"Luke.7.16\"></r>، <r v=\"Acts.15.14\"></r>، <r v=\"Heb.2.6\"></r>؛ </s> <s n=\"(c)\"><b>افتقد بالعقاب</b> (<r v=\"Jer.9.25\"></r>، <r v=\"Ps.89.33\"></r>، وفي مواضع أخرى).†</s>","en":"<f><o>ἐπι-σκέπτομαι</o></f> <et> <e t=\"derivation\">(late form of <g>ἐπισκοπέω</g>, q.v.), </e> <e t=\"septuagint\">[in LXX very freq., chiefly for <h n=\"H6485\">פָּקַד</h> ;]</e> </et> <s n=\"1.\"><b>to inspect, examine</b>. </s> <s n=\"2.\">(a) <b>to visit</b>: c. acc, <r v=\"Acts.7.23\"></r> <r v=\"Acts.15.36\"></r> (cf. <r v=\"Judg.15.1\"></r>); especially, the sick and afflicted (as in MGr. and sometimes in cl.), <r v=\"Matt.25.36\"></r>, <r v=\"Matt.25.43\"></r>, <r v=\"Jas.1.27\"></r> (cf. <r v=\"Sir.7.35\"></r>); </s> <s n=\"(b)\">in LXX and NT (as <h n=\"H6485\">פָּקַד</h> in <r v=\"Gen.21.1\"></r>, <r v=\"Exod.4.31\"></r>, <r v=\"Ps.8.5\"></r>, al.), <b>to visit with help, to care for</b>: <r v=\"Luke.1.68\"></r>, <r v=\"Luke.1.78\"></r> <r v=\"Luke.7.16\"></r>, <r v=\"Acts.15.14\"></r>, <r v=\"Heb.2.6\"></r>; </s> <s n=\"(c)\"><b>to visit with punishment</b> (<r v=\"Jer.9.25\"></r>, <r v=\"Ps.89.33\"></r>, al.; cf. MM, <i>Exp.</i>, xiv; Cremer, 863).†</s>"},"G1983":{"l":"ἐπισκοπέω","o":2,"ar":"<f><o>ἐπι-σκοπέω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>نظر إلى، لاحظ، فحص</b>: يليه <g>μή</g>، <r v=\"Heb.12.15\"></r>. </s> <s n=\"2.\">مثل <g>ἐπισκέπτομαι</g> في السبعينية والعهد الجديد، <b>افتقد، اعتنى بـ (رعى)</b>: <r v=\"1Pet.5.2\"></r>.†</s>","en":"<f><o>ἐπι-σκοπέω</o>, <g>-ῶ</g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6485\">פָּקַד</h> ni., etc. ;] </e> </et> <s n=\"1.\"><b>to look upon, observe, examine</b>: seq. <g>μή</g>, <r v=\"Heb.12.15\"></r>. </s> <s n=\"2.\">As <g>ἐπισκέπτομαι</g> in LXX, NT, <b>to visit, care for</b>: <r v=\"1Pet.5.2\"></r> (R, txt.; WH om.; Cremer, 527).†</s>"},"G1954":{"l":"ἐπίλοιπος","o":1,"ar":"<f><o>ἐπί-λοιπος</o>، <g>-ον</g></f> <s><b>باقٍ، متبقٍّ</b>: <g>χρόνος</g>، <r v=\"1Pet.4.2\"></r>.†</s>","en":"<f><o>ἐπί-λοιπος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>λοιπός</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3498\">יָתַר</h>, <h n=\"H7604\">שָׁאַר</h> ;]</e> </et> <s><b>still left, remaining</b>: <g>χρόνος</g>, <r v=\"1Pet.4.2\"></r>.†</s>"},"G1990":{"l":"ἐπιστήμων","o":1,"ar":"<f><o>ἐπιστήμων</o>، <g>-ον</g>، حالة الجر، <g>-ονoς</g></f> <s><b>عالم، خبير</b>: <r v=\"Jas.3.13\"></r>.†</s>","en":"<f><o>ἐπιστήμων</o>, <g>-ον</g>, gen., <g>-ονoς</g></f> <et> <e t=\"derivation\">(<g>ἐπίσταμαι</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.1.13\"></r> <r v=\"Deut.4.6\"></r>, <r v=\"Isa.5.21\"></r> (<h n=\"H995\">בִּין</h> ni.), <r v=\"1Esd.8.44\"></r>, <r v=\"Sir.10.25\"></r> <r v=\"Sir.21.15\"></r>, etc. ;]</e> </et> <s><b>knowing, skilled</b>: <r v=\"Jas.3.13\"></r>.†</s>"},"G1925":{"l":"ἐπιδείκνυμι","o":7,"ar":"<f><o>ἐπι-δείκνυμι </o></f> <s n=\"1.\"><b>أرى، عرض، أظهر</b>: مع المنصوب والقابل، <r v=\"Matt.16.1\"></r>، <r v=\"Matt.22.19\"></r>، <r v=\"Matt.24.1\"></r>، <r v=\"Luke.17.14\"></r>. والصيغة الوسطى، <b>أظهر لنفسه</b> أو <b>كأنه ملكه</b>: <r v=\"Acts.9.39\"></r>. </s> <s n=\"2.\"><b>بيّن، أشار إلى، برهن</b>: مع المنصوب، <r v=\"Heb.6.17\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.18.28\"></r>.†</s>","en":"<f><o>ἐπι-δείκνυμι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.12.17\"></r> (<h n=\"H6315\">פּוּחַ</h> hi.), <r v=\"Isa.37.26\"></r> (<h n=\"H935\">בּוֹא</h> hi.), Ep. Jer <i>59</i>, <r v=\"2Macc.15.32\"></r>, al ;]</e> </et> <s n=\"1.\"><b>to show, exhibit, display</b>: c. acc et dat., <r v=\"Matt.16.1\"></r> <r v=\"Matt.22.19\"></r> <r v=\"Matt.24.1\"></r>, <r v=\"Luke.17.14\"></r>. Mid., <b>to display for oneself</b> or <b>as one's own</b> (but cf. Bl., § 55, 1): <r v=\"Acts.9.39\"></r>. </s> <s n=\"2.\"><b>to show, point out, prove</b>: c. acc, <r v=\"Heb.6.17\"></r>; c. acc et inf., <r v=\"Acts.18.28\"></r> (cf. MM, <i>Exp.</i>, xiv).†</s>"},"G1989":{"l":"ἐπιστέλλω","o":3,"ar":"<f><o>ἐπι-στέλλω </o></f> <s n=\"1.\"><b>أرسل إلى</b>. </s> <s n=\"2.\"><b>أرسل رسالة</b> مكتوبة، <b>كتب إلى</b>: مع القابل للشخص، <r v=\"Acts.21.25\"></r>، <r v=\"Heb.13.22\"></r>؛ يليه <g>τοῦ</g> مع المصدر، <r v=\"Acts.15.20\"></r>.†</s>","en":"<f><o>ἐπι-στέλλω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.5.8\"></r> <r v=\"Neh.6.19\"></r> (<h n=\"H7971\">שָׁלַח</h>), <r v=\"Jdt.15.4\"></r>, <r v=\"1Macc.10.25\"></r> <r v=\"1Macc.12.7\"></r> <r v=\"1Macc.13.18\"></r> (in each case with v.l. <g>ἀποσ-</g>) * ;] </e> </et> <s n=\"1.\"><b>to send to</b>. </s> <s n=\"2.\"><b>to send a message</b> by letter, <b>to write word</b> (MM, <i>Exp.</i>, xiv): c. dat. pers., <r v=\"Acts.21.25\"></r>, <r v=\"Heb.13.22\"></r>; seq. <g>τοῦ</g>, c. inf., <r v=\"Acts.15.20\"></r>.†</s>"},"G1977":{"l":"ἐπιρίπτω","o":null,"ar":"<f><o>ἐπι-ρίπτω</o></f> <s n=\"1.\"><b>رمى على</b>. </s> <s n=\"2.\"><b>ألقى</b> أو <b>وضع على</b>: مع المنصوب يليه <g>ἐπί</g> مع المنصوب، <r v=\"Luke.19.35\"></r>؛ مجازيًا، <g>τ. μέριμναν</g>، <r v=\"1Pet.5.7\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἐπι-ρίπτω</o></f> <et> <e t=\"derivation\">(Rec. <g>-ρρίπτω</g>, as in cl.), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7993\">שָׁלַךְ</h> hi. ;] </e> </et> <s n=\"1.\"><b>to cast at</b>. </s> <s n=\"2.\"><b>to cast</b> or <b>place upon</b>: c. acc seq. <g>ἐπί</g>, c. acc, <r v=\"Luke.19.35\"></r>; metaph., <g>τ. μέριμναν</g>, <r v=\"1Pet.5.7\"></r> <i>(LXX)</i>.†</s>"},"G1942":{"l":"ἐπικάλυμμα","o":1,"ar":"<f><o>ἐπι-κάλυμμα</o>، <g>-τος, τό</g></f> <s><b>غطاء، ستار</b>: مجازيًا، <g>τ. κακίας</g>، <r v=\"1Pet.2.16\"></r>.†</s>","en":"<f><o>ἐπι-κάλυμμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπικαλύπτω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.26.14\"></r> <r v=\"Exod.39.34\"></r>, (<h n=\"H4374\">מְכַסֶּה</h>), <r v=\"2Kgs.17.19\"></r> (<h n=\"H4539\">מָסָךְ</h>), <r v=\"Job.19.29\"></r> (aliter in <i>Heb.</i>)* ;]</e> </et> <s><b>a cover, veil</b>: metaph., <g>τ. κακίας</g>, <r v=\"1Pet.2.16\"></r>.†</s>"},"G1906":{"l":"ἐπερώτημα","o":1,"ar":"<f>** <o>ἐπ-ερώτημα</o>، <g>-τος, τό </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سؤال، استفسار</b>. </s> <s n=\"2.\"><b>طلب</b>: <r v=\"1Pet.3.21\"></r>.†</s>","en":"<f>** <o>ἐπ-ερώτημα</o>, <g>-τος, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Dan.4.14\"></r> (<h n=\"H7595\">שְׁאֵלָא</h>), <r v=\"Sir.33.3\"></r> * ;] </e> </et> <s n=\"1.\"><b>a question, an inquiry</b> (Hdt., Thuc.). </s> <s n=\"2.\"><b>a demand</b>: <r v=\"1Pet.3.21\"></r> (v. <i>ICC</i>, in l).†</s>"},"G1953":{"l":"ἐπιλησμονή","o":1,"ar":"<f>**† <o>ἐπι-λησμονή</o>، <g>-ῆς, ή</g></f> <s><b>نسيان</b>: <g>ἀκροατὴς ἐ.</g> (مضاف إليه للوصف)، <r v=\"Jas.1.25\"></r>.†</s>","en":"<f>**† <o>ἐπι-λησμονή</o>, <g>-ῆς, ή</g></f> <et> <e t=\"derivation\">(&lt; <g>επιλήθω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.11.27\"></r> * ;]</e> </et> <s><b>forgetful­ness</b>: <g>ἀκροατὴς ἐ.</g> (gen. of qual.), <r v=\"Jas.1.25\"></r>.†</s>"},"G1952":{"l":"ἐπιλείπω","o":1,"ar":"<f><o>ἐπι-λείπω </o></f> <s><b>أعوز، قصّر عن</b>: مع منصوب الشخص، <r v=\"Heb.11.32\"></r>.†</s>","en":"<f><o>ἐπι-λείπω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Obad.1.5\"></r> <h>א</h><i>1</i> R (<h n=\"H7604\">שָׁאַר</h> hi.) * ;] </e> </et> <s><b>to fail</b>: c. acc pers., <r v=\"Heb.11.32\"></r>.†</s>"},"G1926":{"l":"ἐπιδέχομαι","o":2,"ar":"<f>** <o>ἐπι-δέχομαι </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: عن الأشياء، <b>يحتمل، يقبل</b>. وعند الكتّاب المتأخرين، </s> <s n=\"2.\"><b>يقبل فوق ذلك</b>، <b>يقبل</b>: <r v=\"3John.1.9\"></r>. </s> <s n=\"3.\">(a) <b>يقبل فوق ذلك</b>؛ </s> <s n=\"(b)\"><b>يقبل بترحاب، يُضيف</b>: <r v=\"3John.1.10\"></r>† </s>","en":"<f>** <o>ἐπι-δέχομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.13.13\"></r> B<i>2</i>, <r v=\"1Macc.10.1\"></r> <r v=\"1Macc.14.23\"></r>, <r v=\"Sir.51.26\"></r>, al. ;] </e> </et> <s n=\"1.\">in cl., of things, <b>to allow of, admit of</b> (Dem., Arist., al.). In late writers, </s> <s n=\"2.\"><b>to accept besides</b> (Polyb.), <b>to accept</b>; (in <g>π</g>. of the terms of a lease; v. <i>ICC</i>, on III Jo, l.c.): <r v=\"3John.1.9\"></r>. </s> <s n=\"3.\">(a) <b>to receive besides</b> (Menand.); </s> <s n=\"(b)\"><b>to receive hospitably</b> (I Mac, Si, ll c.): <r v=\"3John.1.10\"></r>† </s>"},"G1957":{"l":"ἐπιμαρτυρέω","o":1,"ar":"<f>* <o>ἐπι-μαρτυρέω</o>، <g>-ῶ </g></f> <s><b>يشهد بـ</b>: مع المنصوب والمصدر، <r v=\"1Pet.5.12\"></r>،†</s>","en":"<f>* <o>ἐπι-μαρτυρέω</o>, <g>-ῶ </g></f> <s><b>to bear witness to</b>: c. acc et. inf., <r v=\"1Pet.5.12\"></r>,†</s>"},"G1996":{"l":"ἐπισυνάγω","o":8,"ar":"<f>* <o>ἐπι-συν-άγω </o></f> <s n=\"1.\"><b>جمع معًا</b>: <r v=\"Matt.23.37\"></r>، <r v=\"Matt.24.31\"></r>، <r v=\"Mark.13.27\"></r>، <r v=\"Luke.13.34\"></r>؛ المبني للمجهول، <r v=\"Mark.1.33\"></r>، <r v=\"Luke.12.1\"></r>، <r v=\"Luke.17.37\"></r> (قارن <r v=\"Ps.102.23\"></r>، <r v=\"Ps.106.47\"></r>، <r v=\"2Macc.1.27\"></r>، وفي مواضع أخرى). </s> <s n=\"2.\">في السبعينية: <b>جمع معًا ضد</b> (<r v=\"Mic.4.11\"></r>، <r v=\"Zech.12.3\"></r>، <r v=\"1Macc.3.58\"></r>، وفي مواضع أخرى).†</s>","en":"<f>* <o>ἐπι-συν-άγω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H622\">אָסַף</h>, <h n=\"H6908\">קָבַץ</h>, etc. (Cremer, 65) ;] </e> </et> <s n=\"1.\"><b>to gather together</b>: <r v=\"Matt.23.37\"></r> <r v=\"Matt.24.31\"></r>, <r v=\"Mark.13.27\"></r>, <r v=\"Luke.13.34\"></r>; pass., <r v=\"Mark.1.33\"></r>, <r v=\"Luke.12.1\"></r> <r v=\"Luke.17.37\"></r>, (cf. <r v=\"Ps.102.23\"></r> <r v=\"Ps.106.47\"></r>, <r v=\"2Macc.1.27\"></r>, al.). </s> <s n=\"2.\"><b>to gather together against</b> (<r v=\"Mic.4.11\"></r>, <r v=\"Zech.12.3\"></r>, <r v=\"1Macc.3.58\"></r>, al.).†</s>"},"G1910":{"l":"ἐπιβαίνω","o":6,"ar":"<f><o>ἐπι-βαίνω </o></f> <s n=\"1.\"><b>صعد على، ركب</b>: يليه <g>ἐπί</g> مع المنصوب، <r v=\"Matt.21.5\"></r> <i>(السبعينية)</i>؛ <b>ركب</b> (سفينة)، <b>صعد إلى السفينة</b>: مع القابل، <r v=\"Acts.27.2\"></r>؛ يليه <g>εἰς</g>، <r v=\"Acts.21.6\"></r>؛ مطلقًا، <r v=\"Acts.21.2\"></r>. </s> <s n=\"2.\"><b>صعد إلى، أتى إلى، دخل</b>: يليه <g>εἰς</g>، <r v=\"Acts.20.18\"></r>، <r v=\"Acts.21.4\"></r>؛ مع القابل، <r v=\"Acts.25.1\"></r>.†</s>","en":"<f><o>ἐπι-βαίνω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7392\">רָכַב</h> ;] </e> </et> <s n=\"1.\"><b>to get up on, mount</b>: seq. <g>ἐπί</g>, c. acc, <r v=\"Matt.21.5\"></r> <i>(LXX)</i>; <b>to embark in</b> (a boat), <b>go aboard</b>: c. dat., <r v=\"Acts.27.2\"></r>; seq. <g>εἰς</g>, <r v=\"Acts.21.6\"></r> (Rec.); absol., <r v=\"Acts.21.2\"></r>. </s> <s n=\"2.\"><b>to go up to, go on to, enter</b>: seq. <g>εἰς</g>, <r v=\"Acts.20.18\"></r> <r v=\"Acts.21.4\"></r>; c. dat., <r v=\"Acts.25.1\"></r>.†</s>"},"G1913":{"l":"ἐπιβιβάζω","o":3,"ar":"<f><o>ἐπι-βιβάζω </o></f> <s><b>أركب، وضع على</b>: مع منصوب الشخص، <r v=\"Luke.10.34\"></r>، <r v=\"Luke.19.35\"></r>، <r v=\"Acts.23.24\"></r>.†</s>","en":"<f><o>ἐπι-βιβάζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7392\">רָכַב</h> hi. ;] </e> </et> <s><b>to place upon</b>: c. acc pers., <r v=\"Luke.10.34\"></r> <r v=\"Luke.19.35\"></r>, <r v=\"Acts.23.24\"></r>.†</s>"},"G1900":{"l":"ἐπέκεινα","o":1,"ar":"<f><o>ἐπ-έκεινα </o></f> ظرف <s><b>ما وراء</b>؛ مع المضاف إليه، <r v=\"Acts.7.43\"></r> <i>(السبعينية)</i> †</s>","en":"<f><o>ἐπ-έκεινα </o></f> adv. <et> <e t=\"derivation\">(= <g>ἐπ’ ἐκεῖνα</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.22.27\"></r>, <r v=\"Num.32.19\"></r>, al. (<h n=\"H1973\">הָלְאָה</h>), etc. ;] </e> </et> <s><b>beyond</b>; c. gen., <r v=\"Acts.7.43\"></r> <i>(LXX)</i> †</s>"},"G1963":{"l":"ἐπίνοια","o":2,"ar":"<f><o>ἐπίνοια</o>، <g>-ας, ἡ</g></f> <s><b>فكر، قصد</b>: <r v=\"Acts.8.22\"></r>.†</s>","en":"<f><o>ἐπίνοια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπινοέω</g>, <b>to contrive</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.20.10\"></r>, <r v=\"Wis.6.16\"></r> <r v=\"Wis.9.14\"></r> <r v=\"Wis.14.12\"></r> <r v=\"Wis.15.4\"></r>, <r v=\"Sir.40.2\"></r>, <r v=\"2Macc.12.45\"></r>, <r v=\"4Macc.17.2\"></r> * ;]</e> </et> <s><b>a thought, design</b>: <r v=\"Acts.8.22\"></r>.†</s>"},"G1940":{"l":"ἐπικαθίζω","o":1,"ar":"<f><o>ἐπι-καθ-ίζω </o></f> <s><b><b>جلس على</b></b>: <r v=\"Matt.21.7\"></r>.†</s>","en":"<f><o>ἐπι-καθ-ίζω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7392\">רָכַב</h>, etc. ;] </e> </et> <s><b><b>to sit upon</b></b>: <r v=\"Matt.21.7\"></r>.†</s>"},"G1951":{"l":"ἐπιλέγω","o":null,"ar":"<f><o>ἐπι-λέγω </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>قال فوق ذلك، أضاف قولاً</b>. </s> <s n=\"2.\"><b>سمّى، دعا</b>: <r v=\"John.5.2\"></r>. </s> <s n=\"3.\"><b>اختار</b>؛ الصيغة الوسطى: <b>اختار لنفسه</b>: <r v=\"Acts.15.40\"></r>.†</s>","en":"<f><o>ἐπι-λέγω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H977\">בָּחַר</h> ;] </e> </et> <s n=\"1.\"><b>to say in addition</b> (Hdt.). </s> <s n=\"2.\"><b>to call by name, to call</b>: <r v=\"John.5.2\"></r>. </s> <s n=\"3.\"><b>to choose</b>; mid., <b>to choose for oneself</b>: <r v=\"Acts.15.40\"></r>.†</s>"},"G1964":{"l":"ἐπιορκέω","o":1,"ar":"<f>** <o>ἐπιορκέω</o>، <g>-ῶ</g></f> <s><b>حلف زورًا، حنث بيمينه</b>: <r v=\"Matt.5.33\"></r>.†</s>","en":"<f>** <o>ἐπιορκέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπίορκος</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.1.48\"></r>, <r v=\"Wis.14.28\"></r> * ;] </e> </et> <s><b>to swear falsely, forswear oneself</b>: <r v=\"Matt.5.33\"></r>.†</s>"},"G1995":{"l":"ἐπιστροφή","o":1,"ar":"<f><o>ἐπι-στροφή</o>، <g>-ῆς, ἡ</g></f> <s><b>رجوع، التفات</b>؛ مجازيًا، <b>رجوع (توبة)</b>: <r v=\"Acts.15.3\"></r>.†</s>","en":"<f><o>ἐπι-στροφή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(<g>ἐπιστρέφω</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.47.7\"></r> (<h n=\"H7725\">שׁוּב</h>), <r v=\"Sir.18.21\"></r> <r v=\"Sir.49.2\"></r>, etc. ;] </e> </et> <s><b>a turning about</b>; metaph., <b>conversion</b> (Field, <i>Notes</i>, 246): <r v=\"Acts.15.3\"></r>.†</s>"},"G1915":{"l":"ἐπίβλημα","o":4,"ar":"<f><o>ἐπί-βλημα</o>، <g>-τος, τό </g></f> <s n=\"1.\"><b>ما يُطرح فوق الشيء، غطاء</b>. </s> <s n=\"2.\"><b>ستار منسوج، سجف</b> (<r v=\"Isa.3.22\"></r>). </s> <s n=\"3.\"><b>ما يُوضع على الشيء</b>؛ </s> <s n=\"(a)\"><b>تطريز</b>؛ </s> <s n=\"(b)\"><b>رقعة</b>: <r v=\"Matt.9.16\"></r>، <r v=\"Mark.2.21\"></r>، <r v=\"Luke.5.36\"></r>.†</s>","en":"<f><o>ἐπί-βλημα</o>, <g>-τος, τό </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.3.22\"></r> * ;]</e> </et> <s n=\"1.\"><b>that which is thrown over, a cover</b>. </s> <s n=\"2.\"><b>a tapestry, hanging</b> (<r v=\"Isa.3.22\"></r>). </s> <s n=\"3.\"><b>that which is put on</b>; </s> <s n=\"(a)\"><b>embroidery</b>; </s> <s n=\"(b)\"><b>a patch</b>: <r v=\"Matt.9.16\"></r>, <r v=\"Mark.2.21\"></r>, <r v=\"Luke.5.36\"></r>.†</s>"},"G1991":{"l":"ἐπιστηρίζω","o":4,"ar":"<f><o>ἐπι-στηρίζω </o></f> <s><b>قوّى، شدّد، ثبّت</b>: مع المنصوب، <r v=\"Acts.14.22\"></r> <r v=\"Acts.15.32\"></r>، <r v=\"Acts.15.41\"></r>.†</s>","en":"<f><o>ἐπι-στηρίζω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5564\">סָמַךְ</h>, etc. ;] </e> </et> <s><b>to make stronger, confirm</b>: c. acc, <r v=\"Acts.14.22\"></r> <r v=\"Acts.15.32\"></r>, <r v=\"Acts.15.41\"></r>.†</s>"},"G1920":{"l":"ἐπιγίνομαι","o":1,"ar":"<f>** <o>ἐπι-γίνομαι</o> (انظر تحت مدخل <g>γίνομαι</g>) </f> <s><b>حدث، هبّ، طرأ</b>: <r v=\"Acts.28.13\"></r>.†</s>","en":"<f>** <o>ἐπι-γίνομαι</o> (v.s. <g>γίνομαι</g>) </f> <et> <e t=\"septuagint\">[in LXX: Ep. <r v=\"Jer.47.1-Jer.47.7\"></r>, <r v=\"3Macc.2.6\"></r> * ;] </e> </et> <s><b>to arrive, arise, come on</b>: <r v=\"Acts.28.13\"></r>.†</s>"},"G1960":{"l":"ἐπιμελῶς","o":1,"ar":"<f><o>ἐπιμελῶς </o></f> ظرف، <s><b>باجتهاد، بعناية</b>: <r v=\"Luke.15.8\"></r>.†</s>","en":"<f><o>ἐπιμελῶς </o></f> adv., <et> <e t=\"septuagint\">[in LXX for <h n=\"H7535\">רַק</h>, etc. ;] </e> </et> <s><b>carefully</b>: <r v=\"Luke.15.8\"></r>.†</s>"},"G1927":{"l":"ἐπιδημέω","o":2,"ar":"<f>* <o>ἐπι-δημέω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>كان في وطنه</b>، </s> <s n=\"2.\"><b>أقام</b> في مكان، <b>تغرّب، نزل</b>: <r v=\"Acts.2.10\"></r>، <r v=\"Acts.17.21\"></r>؛ يليه <g>ἐν</g>، <r v=\"Acts.18.27\"></r>.†</s>","en":"<f>* <o>ἐπι-δημέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>δῆμος</g>); </e> </et> <s n=\"1.\"><b>to be at home</b> (Thuc., Plat., al.), </s> <s n=\"2.\"><b>to stay in</b> a place, <b>sojourn</b> (Plat., Xen., al.; and v. MM, <i>Exp.</i>, xiv): <r v=\"Acts.2.10\"></r> <r v=\"Acts.17.21\"></r>; seq. <g>ἐν</g>, <r v=\"Acts.18.27\"></r> (WH, mg.).†</s>"},"G1917":{"l":"ἐπιβουλή","o":4,"ar":"<f><o>ἐπι-βουλή</o>، <g>-ῆς, ἡ </g></f> <s><b>تدبير ضد أحد، مكيدة</b>: <r v=\"Acts.9.24\"></r>، <r v=\"Acts.20.3\"></r>، <r v=\"Acts.20.19\"></r>، <r v=\"Acts.23.30\"></r>.†</s>","en":"<f><o>ἐπι-βουλή</o>, <g>-ῆς, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.2.22\"></r>, <r v=\"1Esd.5.73\"></r>, <r v=\"2Macc.5.7\"></r>, al. ;] </e> </et> <s><b>a plan against, a plot</b>: <r v=\"Acts.9.24\"></r> <r v=\"Acts.20.3\"></r>, <r v=\"Acts.20.19\"></r> <r v=\"Acts.23.30\"></r>.†</s>"},"G1967":{"l":"ἐπιούσιος","o":2,"ar":"<f>*† <o>ἐπιούσιος</o>، <g>-ον</g></f> <s>لا ترد إلا في العبارة <g>ἄρτος ἐ.</g>، وفي الترجمات الإنجليزية: <b>اليومي (كفاف اليوم)</b>؛ وفي هامش الترجمة المنقحة: <b>لليوم الآتي</b>: <r v=\"Matt.6.11\"></r>، <r v=\"Luke.11.3\"></r>. (تؤيَّد عدة اشتقاقات، يشير كل منها إلى معنى مختلف.) </s> <s n=\"1.\">مشتقة من <g>ἐπιοῦσα</g> (أي <g>ἡμέρα</g>) (أو مشتقة من <g>ἐπὶ</g> <g>τὴν ἰοῦσαν</g>، أي <g>ήμέραν</g>)، ومن ثم <b>للغد</b> أو <b>لليوم الآتي</b>. </s> <s n=\"2.\"></s> <s n=\"(a)\">مشتقة من <g>ἐπί</g> + <g>οὐσία</g>، ومن ثم <b>للقوت، الضروري</b>؛ </s> <s n=\"(b)\">مشتقة من <g>ἐπί</g> + <g>εἶναι</g> في صيغة اسم الفاعل المؤنث، ومن ثم <b>الخاص بـ</b> (اليوم). والترجمة <b>اليومي</b> مبنية على الفولجاتا (<l>quotidianus</l>).†</s>","en":"<f>*† <o>ἐπιούσιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(cf. <g>περιούσιος</g>, [in LXX for <h n=\"H5459\">סְגֻלָּה</h>, <r v=\"Deut.7.6\"></r>, etc.]), </e> </et> <s>found only in the phrase <g>ἄρτος ἐ.</g>, EV, <b>daily</b>; R, mg., <b>for the coming day</b>: <r v=\"Matt.6.11\"></r>, <r v=\"Luke.11.3\"></r>. (Several derivations find support, each pointing to a different meaning. </s> <s n=\"1.\">&lt; <g>ἐπιοῦσα</g> (sc. <g>ἡμέρα</g>) (or, &lt; <g>ἐπὶ</g> <g>τὴν ἰοῦσαν</g> (sc. <g>ήμέραν</g>), Zorell, s.v.), hence, <b>for the morrow</b> or <b>for the coming day</b> (R, mg.). </s> <s n=\"2.\"></s> <s n=\"(a)\">&lt; <g>ἐπί</g> + <g>οὐσία</g>, hence, <b>for subsistence, needful</b> (Am. R, mg.); </s> <s n=\"(b)\">&lt; <g>ἐπί</g> + <g>εἶναι</g> in fem. ptcp. form, hence, <b>pertaining to</b> (the day). For renderings of versions and views of various writers, v. reff. in <i>DB</i>, <i>ext.</i>, 36 f.; <i>DCG</i>, ii, 58 f., 62<i>a</i>; <i>ICC</i> on Lk, l.c. The EV, <b>daily</b>, is based on the Vg. (Lk; OL, Mt, Lk, <l>quotidianus</l>). \"It is difficult not to think that <g>τὸν ἐ.</g> rests upon misunderstanding of an original Aramaic phrase, or upon a Greek corruption\" (<i>ICC</i> on Mt, l.c.; cf. also Cremer, 239).†</s>"},"G1975":{"l":"ἐπιπορεύομαι","o":1,"ar":"<f>† <o>ἐπι-πορεύομαι </o></f> <s><b>سافر، ارتحل إلى</b>: يليه <g>πρός</g>، مع منصوب الشخص، <r v=\"Luke.8.4\"></r>.†</s>","en":"<f>† <o>ἐπι-πορεύομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.26.33\"></r> (<h n=\"H309\">אָחַר</h>), <r v=\"Ezek.39.14\"></r> (<h n=\"H5674\">עָבַר</h>), Ep. Je <i>62</i>, <r v=\"2Macc.2.28\"></r>, <r v=\"3Macc.1.4\"></r> * ;]</e> </et> <s><b>to travel, journey to</b>: seq. <g>πρός</g>, c. acc pers., <r v=\"Luke.8.4\"></r>.†</s>"},"G1948":{"l":"ἐπικρίνω","o":1,"ar":"<f>** <o>ἐπι-κρίνω </o></f> <s><b>قضى، أصدر حكمًا</b>: مع المنصوب والمصدر، <r v=\"Luke.23.24\"></r>.†</s>","en":"<f>** <o>ἐπι-κρίνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.4.47\"></r>, <r v=\"3Macc.4.2\"></r> * ;] </e> </et> <s><b>to decree, give sentence</b>: c. acc et inf., <r v=\"Luke.23.24\"></r>.†</s>"},"G1947":{"l":"ἐπικουρία","o":1,"ar":"<f>** <o>ἐπικουρία</o>، <g>-ας, ἡ</g></f> <s><b>عون، معونة</b>: <r v=\"Acts.26.22\"></r>.†</s>","en":"<f>** <o>ἐπικουρία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπικουρέω</g> to be an <g>ἐπίκουρος</g>, <b>an ally</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.13.18\"></r> * ;]</e> </et> <s><b>aid, assistance</b>: <r v=\"Acts.26.22\"></r>.†</s>"},"G1966":{"l":"ἔπειμι","o":null,"ar":"<f><o>ἔπ-ειμι </o></f> <s n=\"1.\"><b>أقبل على، اقترب</b> </s> <s n=\"2.\">عن الزمن، <b>أتى</b> أو <b>تلا</b>؛ غالبًا اسم فاعل، <g>ἐπιών, -οῦσα, όν</g>، <b>التالي، اللاحق</b>: <g>τῇ- ἔ.</g> (بتقدير <g>ἡμέρᾳ</g>، كما يكثر في اليونانية المتأخرة)، <r v=\"Acts.16.11\"></r> <r v=\"Acts.20.15\"></r> <r v=\"Acts.21.18\"></r>؛ <g>ἡμέρᾳ</g> (كالمعتاد في الكلاسيكية)، <r v=\"Acts.7.26\"></r>؛ <g>νυκτί</g>، <r v=\"Acts.23.11\"></r>.†</s>","en":"<f><o>ἔπ-ειμι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.8.22\"></r> (<h n=\"H5975\">עָמַד</h>), <r v=\"Sir.42.19\"></r>, etc. ;] </e> </et> <s n=\"1.\"><b>to come upon, approach</b> </s> <s n=\"2.\">Of time, <b>to come on</b> or <b>after</b>; mostly as ptcp., <g>ἐπιών, -οῦσα, όν</g>, <b>next, following</b>: <g>τῇ- ἔ.</g> (sc. <g>ἡμέρᾳ</g>, as freq. in late Gk.), <r v=\"Acts.16.11\"></r> <r v=\"Acts.20.15\"></r> <r v=\"Acts.21.18\"></r>; <g>ἡμέρᾳ</g> (as usual in cl.), <r v=\"Acts.7.26\"></r>; <g>νυκτί</g>, <r v=\"Acts.23.11\"></r>.†</s>"},"G1982":{"l":"ἐπισκιάζω","o":5,"ar":"<f><o>ἐπι-σκιάζω </o></f> <s><b>ألقى ظلًّا على، ظلّل</b>: مع القابل، <r v=\"Acts.5.15\"></r>؛ عن سحابة منيرة (متى، في الموضع المذكور، وقارن <r v=\"Exod.40.29\"></r>، <r v=\"Exod.40.35\"></r>، <r v=\"2Macc.2.8\"></r>)، مع القابل، <r v=\"Mark.9.7\"></r>؛ مع المنصوب، <r v=\"Matt.17.5\"></r>، <r v=\"Luke.9.34\"></r>؛ مجازيًا (قارن المزامير والأمثال، في المواضع المذكورة)، عن الروح القدس، <r v=\"Luke.1.35\"></r>.†</s>","en":"<f><o>ἐπι-σκιάζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.40.35\"></r> (<h n=\"H7931\">שָׁכַן</h>), <r v=\"Ps.91.4\"></r> <r v=\"Ps.140.7\"></r> (<h n=\"H5526\">סָכַךְ</h>), <r v=\"Prov.18.11\"></r> * ;]</e> </et> <s><b>to throw a shadow upon, overshadow</b>: c. dat., <r v=\"Acts.5.15\"></r>; of a shining (Mt, l.c., and cf. <r v=\"Exod.40.29\"></r>, <r v=\"Exod.40.35\"></r>, <r v=\"2Macc.2.8\"></r>) cloud, c. dat., <r v=\"Mark.9.7\"></r>; c. acc, <r v=\"Matt.17.5\"></r>, <r v=\"Luke.9.34\"></r>; metaph. (cf. Pss, Pr, ll.c.), of the Holy Spirit, <r v=\"Luke.1.35\"></r>.†</s>"},"G1923":{"l":"ἐπιγραφή","o":5,"ar":"<f>* <o>ἐπι-γραφή</o>، <g>-ῆς, ἡ</g></f> <s><b>عنوان، كتابة منقوشة</b>: <r v=\"Matt.22.20\"></r>، <r v=\"Mark.12.16\"></r> <r v=\"Mark.15.26\"></r>، <r v=\"Luke.20.24\"></r> <r v=\"Luke.23.38\"></r>.†</s>","en":"<f>* <o>ἐπι-γραφή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπιγράφω</g>), </e> </et> <s><b>an inscription</b>: <r v=\"Matt.22.20\"></r>, <r v=\"Mark.12.16\"></r> <r v=\"Mark.15.26\"></r>, <r v=\"Luke.20.24\"></r> <r v=\"Luke.23.38\"></r>.†</s>"},"G1903":{"l":"ἐπενδύτης","o":1,"ar":"<f><o>ἐπενδύτης</o>، <g>-ου, ὁ</g></f> <s><b>قميص خارجي، رداء</b>: <r v=\"John.21.7\"></r> .†</s>","en":"<f><o>ἐπενδύτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπενδύω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4598\">מְעִיל</h> <r v=\"Lev.8.7\"></r> A (Aq. <g>ἐπένδυμα</g>), <r v=\"1Kgs.18.4\"></r> A, <r v=\"2Kgs.13.18\"></r> * ;] </e> </et> <s><b>an outer tunic</b> (RV, coat): <r v=\"John.21.7\"></r> .†</s>"},"G1956":{"l":"ἐπιλύω","o":2,"ar":"<f>** <o>ἐπι-λύω </o></f> <s n=\"1.\"><b>حلّ، أطلق</b>. </s> <s n=\"2.\"><b>حلّ، فصل، فسّر</b>: <r v=\"Mark.4.34\"></r>، <r v=\"Acts.19.39\"></r>.†</s>","en":"<f>** <o>ἐπι-λύω </o></f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Gen.40.8\"></r> <r v=\"Gen.41.8\"></r>, <r v=\"Gen.41.12\"></r>; <i>Th.</i>: <r v=\"Hos.3.4\"></r> * ;] </e> </et> <s n=\"1.\"><b>to loose, release</b>. </s> <s n=\"2.\"><b>to solve, settle, explain</b>: <r v=\"Mark.4.34\"></r>, <r v=\"Acts.19.39\"></r>.†</s>"},"G1946":{"l":"Ἐπικούριος","o":1,"ar":"<f>† <o>Ἐπικούριος</o>، <g>-ου, ὁ</g> </f> <s><b>أبيكوري</b>، من أتباع أبيكورس: <r v=\"Acts.17.18\"></r>.†</s>","en":"<f>† <o>Ἐπικούριος</o> (Rec. <g>-ειος</g>), <g>-ου, ὁ</g> </f> <s><b>an Epicurean</b>, a follower of Epicurus: <r v=\"Acts.17.18\"></r>.†</s>"},"G1962":{"l":"ἐπινεύω","o":1,"ar":"<f><o>ἐπι-νεύω </o></f> <s><b>أومأ</b> أمرًا أو موافقةً، <b>أومأ بالموافقة، رضي</b>: <r v=\"Acts.18.20\"></r>.†</s>","en":"<f><o>ἐπι-νεύω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.26.24\"></r> (<h n=\"H5234\">נָכַר</h> ni.), <r v=\"1Macc.6.57\"></r>, <r v=\"2Macc.4.10\"></r> <r v=\"2Macc.11.\"></r> <r v=\"2Macc.14.20\"></r> * ;]</e> </et> <s><b>to nod</b> in command or approval, <b>to nod approval, consent</b>: <r v=\"Acts.18.20\"></r>.†</s>"},"G1929":{"l":"ἐπιδίδωμι","o":9,"ar":"<f><o>ἐπι-δίδωμι </o></f> <s n=\"1.\"><b>سلّم، ناول</b>: مع منصوب الشيء وقابل الشخص، <r v=\"Matt.7.9\"></r>، <r v=\"Matt.7.10\"></r>، <r v=\"Luke.11.11\"></r>، <r v=\"Luke.11.12\"></r>، <r v=\"Luke.24.30\"></r>، <r v=\"Luke.24.42\"></r>، <r v=\"Acts.15.30\"></r>؛ المبني للمجهول مع قابل الشخص، <r v=\"Luke.4.17\"></r>. </s> <s n=\"2.\"><b>استسلم، أذعن</b>: مطلقًا، <r v=\"Acts.27.15\"></r>.†</s>","en":"<f><o>ἐπι-δίδωμι </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5414\">נָתַן</h>, etc. ;] </e> </et> <s n=\"1.\"><b>to give over, to hand</b>: c. acc rei et dat. pers., <r v=\"Matt.7.9\"></r>, <r v=\"Matt.7.10\"></r>, <r v=\"Luke.11.11\"></r>, <r v=\"Luke.11.12\"></r> <r v=\"Luke.24.30\"></r>, <r v=\"Luke.24.42\"></r>, <r v=\"Acts.15.30\"></r>; pass. c. dat. pers., <r v=\"Luke.4.17\"></r>. </s> <s n=\"2.\"><b>to give in, give way</b>: absol., <r v=\"Acts.27.15\"></r>.†</s>"},"G1918":{"l":"ἐπιγαμβρεύω","o":1,"ar":"<f>† <o>ἐπι-γαμβρεύω</o></f> <s n=\"1.\"><b>صاهر</b>: مع القابل (في السبعينية في المواضع المذكورة، ما عدا <r v=\"Gen.38.8\"></r>). </s> <s n=\"2.\"><b>تزوّج</b> (بصفته أقرب أقرباء الزوج المتوفى، قارن <r v=\"Gen.38.8\"></r>): مع المنصوب، <r v=\"Matt.22.24\"></r>.†</s>","en":"<f>† <o>ἐπι-γαμβρεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>γαμβρός</g>, <b>a connection by marriage</b>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.34.9\"></r>, <r v=\"1Sam.18.21\"></r> <i>ff.</i>, <r v=\"2Chr.18.1\"></r>, <r v=\"Ezra.9.14\"></r> (<h n=\"H2859\">חָתַן</h> hithp.), <r v=\"Gen.38.8\"></r> R (<h n=\"H2992\">יָבַם</h> pi.), <r v=\"1Macc.10.54\"></r>, <r v=\"1Macc.10.56\"></r> * ;] </e> </et> <s n=\"1.\"><b>to enter into affinity with</b>: c. dat. (LXX, ll. c., exc. <r v=\"Gen.38.8\"></r>). </s> <s n=\"2.\"><b>to marry</b> (as deceased husband's next of kin, cf. <r v=\"Gen.38.8\"></r>): c. acc, <r v=\"Matt.22.24\"></r>.†</s>"},"G1988":{"l":"ἐπιστάτης","o":7,"ar":"<f><o>ἐπιστάτης</o>، <g>-ου, ό</g></f> <s><b>رئيس، قائد، معلّم (سيّد)</b>: <r v=\"Luke.5.5\"></r>، <r v=\"Luke.8.24\"></r>، <r v=\"Luke.8.45\"></r>، <r v=\"Luke.9.33\"></r>، <r v=\"Luke.9.49\"></r>، <r v=\"Luke.17.13\"></r>.†</s>","en":"<f><o>ἐπιστάτης</o>, <g>-ου, ό</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐφίστημι</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.25.19\"></r>, <r v=\"Jer.29.26\"></r> <r v=\"Jer.52.25\"></r> (<h n=\"H6496\">פָּקִיד</h>), <r v=\"2Chr.31.12\"></r> (<h n=\"H5057\">נָגִיד</h>), <r v=\"2Macc.5.22\"></r>, etc. ;] </e> </et> <s><b>a chief, commander, master</b>: <r v=\"Luke.5.5\"></r> <r v=\"Luke.8.24\"></r>, <r v=\"Luke.8.45\"></r> <r v=\"Luke.9.33\"></r>, <r v=\"Luke.9.49\"></r> <r v=\"Luke.17.13\"></r> (cf. Dalman, <i>Words</i>, 336 ff.).†</s>"},"G1979":{"l":"ἐπισιτισμός","o":1,"ar":"<f><o>ἐπισιτισμός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\"><b>التزوّد بالمؤن</b>. </s> <s n=\"2.\"><b>مؤونة، طعام</b>: <r v=\"Luke.9.12\"></r>.†</s>","en":"<f><o>ἐπισιτισμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐπισιτίζομαι</g>, <b>to supply with provisions</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.42.25\"></r>, al. (<h n=\"H6720\">צֵדָה</h>), <r v=\"Jdt.2.18\"></r> <r v=\"Jdt.4.5\"></r> ;] </e> </et> <s n=\"1.\"><b>a foraging</b>. </s> <s n=\"2.\"><b>provisions, food</b>: <r v=\"Luke.9.12\"></r>.†</s>"},"G1976":{"l":"ἐπιράπτω","o":3,"ar":"<f>*† <o>ἐπι-ράπτω</o>، </f> <s><b>خاط على</b>: يليه <g>ἐπί</g> مع المنصوب، <r v=\"Mark.2.21\"></r>.†</s>","en":"<f>*† <o>ἐπι-ράπτω</o> (Rec. <g>-ρράπτω</g>), </f> <s><b>to sew upon</b>: seq. <g>ἐπί</g>, c. acc, <r v=\"Mark.2.21\"></r>.†</s>"},"G1998":{"l":"ἐπισυντρέχω","o":1,"ar":"<f>† <o>ἐπι-συν-τρέχω </o></f> <s><b>تراكض معًا ثانيةً</b>: <r v=\"Mark.9.25\"></r>.†</s>","en":"<f>† <o>ἐπι-συν-τρέχω </o></f> <s><b>to run together again</b>: <r v=\"Mark.9.25\"></r> (v. Swete, in l.).†</s>"}});A.got[19]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});